PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE settings (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL,
    description TEXT,
    updated_at INTEGER NOT NULL
);
CREATE TABLE lessons (
    id TEXT PRIMARY KEY,
    subject TEXT NOT NULL,
    grade TEXT NOT NULL,
    unit TEXT NOT NULL,
    title TEXT NOT NULL,
    archived INTEGER DEFAULT 0,
    created_at INTEGER NOT NULL
);
CREATE TABLE lesson_chunks (
    id TEXT PRIMARY KEY,
    course_id TEXT,
    lesson_id TEXT,
    stage TEXT,
    kind TEXT DEFAULT 'شرح',
    status TEXT DEFAULT 'draft',
    text TEXT NOT NULL,
    keywords TEXT NOT NULL, -- JSON array of strings
    grade TEXT,
    unit TEXT,
    subject TEXT,
    source_note TEXT,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);
CREATE TABLE self_learning_pending (
    id TEXT PRIMARY KEY,
    text TEXT NOT NULL,
    keywords TEXT NOT NULL,
    grade TEXT,
    unit TEXT,
    subject TEXT,
    status TEXT DEFAULT 'pending', -- 'pending' | 'approved' | 'rejected'
    created_at INTEGER NOT NULL
);
CREATE TABLE intents (
    core_id TEXT PRIMARY KEY,
    intent TEXT NOT NULL,
    category TEXT NOT NULL,
    answer TEXT NOT NULL,
    variations TEXT NOT NULL -- JSON array of strings
);
CREATE TABLE learned_answers (
    id TEXT PRIMARY KEY,
    question TEXT NOT NULL,
    question_norm TEXT NOT NULL,
    answer TEXT NOT NULL,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);
CREATE TABLE chat_logs (
    id TEXT PRIMARY KEY,
    student_uid TEXT NOT NULL,
    user_message TEXT NOT NULL,
    bot_reply TEXT NOT NULL,
    source TEXT NOT NULL, -- 'intent' | 'cache' | 'llm_groq' | 'llm_gemini' | 'system_override'
    cpu_ms REAL,
    rating INTEGER DEFAULT NULL, -- 1 for 👍, -1 for 👎
    created_at INTEGER NOT NULL
);
CREATE TABLE usage_daily (
    id TEXT PRIMARY KEY, -- 'YYYY-MM-DD:student_uid' OR 'YYYY-MM-DD:GLOBAL'
    date_key TEXT NOT NULL, -- 'YYYY-MM-DD'
    user_uid TEXT NOT NULL,
    count INTEGER DEFAULT 0
);
CREATE TABLE answer_cache (
    question_hash TEXT PRIMARY KEY,
    question_norm TEXT NOT NULL,
    answer TEXT NOT NULL,
    source TEXT NOT NULL,
    created_at INTEGER NOT NULL,
    expires_at INTEGER NOT NULL
);
CREATE TABLE conversation_states (
    student_uid TEXT PRIMARY KEY,
    bot_paused INTEGER DEFAULT 0,
    admin_active INTEGER DEFAULT 0,
    last_student_message_at INTEGER,
    last_admin_message_at INTEGER,
    last_activity_at INTEGER NOT NULL,
    unread_for_admin INTEGER DEFAULT 0
);
CREATE INDEX idx_chunks_lesson ON lesson_chunks(lesson_id);
CREATE INDEX idx_chunks_grade ON lesson_chunks(grade);
CREATE INDEX idx_chunks_course_lesson ON lesson_chunks(course_id, lesson_id);
CREATE INDEX idx_chunks_stage ON lesson_chunks(stage);
CREATE INDEX idx_chunks_status ON lesson_chunks(status);
CREATE INDEX idx_self_learning_status ON self_learning_pending(status);
CREATE INDEX idx_learned_norm ON learned_answers(question_norm);
CREATE INDEX idx_chat_logs_created ON chat_logs(created_at);
CREATE INDEX idx_chat_logs_rating ON chat_logs(rating);
CREATE INDEX idx_chat_logs_student ON chat_logs(student_uid);
CREATE INDEX idx_usage_date ON usage_daily(date_key);
CREATE INDEX idx_cache_expires ON answer_cache(expires_at);
CREATE INDEX idx_conv_unread ON conversation_states(unread_for_admin);
CREATE INDEX idx_conv_activity ON conversation_states(last_activity_at);
