INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('0LqhHEkBZwrk0x5qow23','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','جبال قارة آسيا أعلى جبال في اسيا قمة إفرست. جبال الهيمالايا هي أعلى وأضخم السلاسل الجبلية في العالم وتوجد بها قمة إفرست أعلى قمة جبلية (8848م).','["جبال","قاره","اسيا","اعلي","قمه","افرست","الهيمالايا","واضخم","السلاسل","الجبليه","العالم","وتوجد","بها","جبليه","8848م"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156205561,1785156205561);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('0f27GeXFR6jy1MUwsTIr','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','"النيل ساعد في قيام الحضارة ليه؟", "ما أهمية نهر النيل للمصريين القدماء؟", "علل اعتماد المصريين القدماء على النيل.", "لماذا قامت الحضارة بالقرب من النيل؟", "النيل كان سبب الحضارة؟", "ايه علاقة النيل بالحضارة المصرية؟", "وضح دور النيل في الحضارة.", "لماذا ازدهرت الحضارة المصرية عند النيل؟", "ما العوامل التي ساعدت على قيام الحضارة المصرية؟",','["النيل","ساعد","قيام","الحضاره","ليه؟","اهميه","نهر","للمصريين","القدماء؟","علل","اعتماد","المصريين","القدماء","علي","لماذا","قامت","بالقرب","النيل؟","سبب","الحضاره؟","ايه","علاقه","بالحضاره","المصريه؟","وضح","دور","ازدهرت","المصريه","العوامل","ساعدت"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027 - (برمجيات)','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785166908950,1785166908950);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('0pzGup07BElNm030GyzG','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','"العوامل الطبيعيه لقيام الحضاره"','["العوامل","الطبيعيه","لقيام","الحضاره"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027 - (برمجيات)','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785166909235,1785166909235);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('17kaPLUFuM9T4MIUG1CM','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','"لماذا قامت الحضارة المصرية على نهر النيل؟", "ليه قامت الحضارة المصرية على ضفاف النيل؟", "ما سبب قيام الحضارة المصرية على نهر النيل؟", "اذكر سبب قيام الحضارة المصرية على النيل.", "لماذا استقرت الحضارة المصرية حول نهر النيل؟", "ما أسباب قيام الحضارة المصرية القديمة؟", "لماذا كان نهر النيل أساس الحضارة المصرية؟",','["لماذا","قامت","الحضاره","المصريه","علي","نهر","النيل؟","ليه","ضفاف","سبب","قيام","اذكر","النيل","استقرت","اسباب","القديمه؟","اساس","المصريه؟"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027 - (برمجيات)','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785166908681,1785166908681);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('4gRkOY0gFufTss23Fwxi','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','مساحة قارة أوروبا مساحتها كام تبلغ قد ايه حجم قارة اوروبا. تعد قارة أوروبا سادس قارات العالم من حيث المساحة؛ حيث تبلغ مساحتها نحو 10.5 مليون كم2 (7% من مساحة اليابس).','["مساحه","قاره","اوروبا","مساحتها","كام","تبلغ","ايه","حجم","تعد","سادس","قارات","العالم","حيث","المساحه؛","نحو","مليون","كم2","اليابس"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156203224,1785156203224);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('6H0TT9gSqAyoivprjpVr','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','"يعني اي مناخ", "الفرق بنهم" "core_id": "Q_002", "intent": "قيام_الحضارة_المصرية", "category": "academic", "answer": "قامت الحضارة المصرية على ضفاف نهر النيل لتوافر المياه، وخصوبة التربة، وقيام الزراعة، وسهولة النقل والاتصال، واستقرار السكان.", "variations": [ "علل قيام الحضارة المصرية القديمة على ضفاف نهر النيل.",','["يعني","مناخ","الفرق","بنهم","core","002","intent","قيام","الحضاره","المصريه","category","academic","answer","قامت","علي","ضفاف","نهر","النيل","لتوافر","المياه،","وخصوبه","التربه،","وقيام","الزراعه،","وسهوله","النقل","والاتصال،","واستقرار","السكان","variations","علل","القديمه"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027 - (برمجيات)','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785166908572,1785166908572);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('AWl0LfEwNxdL7oTpnzvt','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','أهمية السهول الفيضية بأوروبا بم تفسر. ساعدت السهول الفيضية على سهولة الاتصال بين أجزاء القارة وتحقيق التنمية الزراعية.','["اهميه","السهول","الفيضيه","باوروبا","تفسر","ساعدت","علي","سهوله","الاتصال","اجزاء","القاره","وتحقيق","التنميه","الزراعيه"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156206348,1785156206348);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('CggDQKeAkDHZRyW8dKmN','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','"الفرق بين الطقس والمناخ؟", "عرف الفرق بين الطقس والمناخ.", "قارن بين الطقس والمناخ.", "ما أوجه الاختلاف بين الطقس والمناخ؟", "وضح الفرق بين الطقس والمناخ.", "الطقس والمناخ نفس الحاجة؟", "الطقس غير المناخ؟", "هل الطقس يختلف عن المناخ؟", "ما المقصود بالطقس والمناخ؟", "الطقس يعني ايه والمناخ يعني ايه؟", "اشرح الفرق بين الطقس والمناخ.",','["الفرق","الطقس","والمناخ؟","عرف","والمناخ","قارن","اوجه","الاختلاف","وضح","نفس","الحاجه؟","المناخ؟","يختلف","المقصود","بالطقس","يعني","ايه","ايه؟","اشرح"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027 - (برمجيات)','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785166908045,1785166908045);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('D2GVZOXyf74pJGIrAxJw','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','السهول الساحلية في قارة أوروبا تعاريج السواحل المواني الطبيعية. تتميز سواحل أوروبا بكثرة التعاريج مما ساعد على قيام العديد من المواني الطبيعية.','["السهول","الساحليه","قاره","اوروبا","تعاريج","السواحل","المواني","الطبيعيه","تتميز","سواحل","بكثره","التعاريج","مما","ساعد","علي","قيام","العديد"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156206682,1785156206682);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('Dobrkw9VeZYFdiCanlFk','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','"علل نشأة الحضارة المصرية القديمة.", "سبب ازدهار الحضارة المصرية القديمة.", "النيل والحضارة المصرية.", "كيف قامت الحضارة المصرية؟", "علل أهمية نهر النيل في نشأة الحضارة.", "بم تفسر قيام الحضارة المصرية", "بم تفسر اهمية نهر النيل", "ليه الحضارة المصريه قامت علي النيل", "اهميه نهر النيل قديما", "اسباب قيام الحضاره المصريه القديمه",','["علل","نشاه","الحضاره","المصريه","القديمه","سبب","ازدهار","النيل","والحضاره","كيف","قامت","المصريه؟","اهميه","نهر","تفسر","قيام","ليه","علي","قديما","اسباب"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027 - (برمجيات)','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785166909096,1785166909096);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('DrcMnIkKFChXzcx5684N','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','الموقع الجغرافي لقارة أوروبا يحدها ايه المحيطات البحار. يحدها شمالا المحيط القطبي الشمالي، وجنوبا البحر المتوسط والأسود، وغربا المحيط الأطلنطي، وشرقا قارة آسيا.','["الموقع","الجغرافي","لقاره","اوروبا","يحدها","ايه","المحيطات","البحار","شمالا","المحيط","القطبي","الشمالي،","وجنوبا","البحر","المتوسط","والاسود،","وغربا","الاطلنطي،","وشرقا","قاره","اسيا"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156204864,1785156204864);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('DssEo0wgXaf8fcm2RWhS','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','ما النتائج المترتبة على الموقع الفلكي لقارة آسيا نتائج امتدادها الفلكي. أدى ذلك لوقوعها في النصف الشمالي للكرة الأرضية (عدا جزر إندونيسيا)، وأدى إلى تنوع كبير في مناخها ونباتاتها الطبيعية وحيواناتها ومحاصيلها الزراعية.','["النتاءج","المترتبه","علي","الموقع","الفلكي","لقاره","اسيا","نتاءج","امتدادها","ادي","لوقوعها","النصف","الشمالي","للكره","الارضيه","عدا","جزر","اندونيسيا","وادي","الي","تنوع","كبير","مناخها","ونباتاتها","الطبيعيه","وحيواناتها","ومحاصيلها","الزراعيه"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156203569,1785156203569);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('GoW4cToDfmiZWFIHw82k','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','الموقع الفلكي لقارة آسيا دوائر العرض خطوط الطول. تمتد من دائرة عرض 10 جنوبًا إلى 81 شمالا، وتمتد من خط طول 26 شرقًا حتى 170 غربا، وهي أكبر قارات العالم من حيث الامتداد الفلكي.','["الموقع","الفلكي","لقاره","اسيا","دواءر","العرض","خطوط","الطول","تمتد","داءره","عرض","جنوبًا","الي","شمالا،","وتمتد","طول","شرقًا","حتي","170","غربا،","وهي","اكبر","قارات","العالم","حيث","الامتداد"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156203454,1785156203454);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('Hez2jBLcVoelB6NRz3V0','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','السهول الفيضية في قارة أوروبا السهل الأوروبي العظيم أنهار أوروبا نهر الفولجا أطول أنهار أوروبا نهر الدانوب. يُعد السهل الأوروبي العظيم أكبر السهول الفيضية ويجري فيه نهر الفولجا (أطول أنهار أوروبا) ونهر الدانوب.','["السهول","الفيضيه","قاره","اوروبا","السهل","الاوروبي","العظيم","انهار","نهر","الفولجا","اطول","الدانوب","يُعد","اكبر","ويجري","فيه","ونهر"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156206229,1785156206229);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('JU1XxSIFsWaZ0S89olLR','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','الأهمية الدينية لموقع قارة آسيا بم تفسر اهميتها الدينيه. تعد مهد الديانات السماوية (اليهودية والمسيحية والإسلام) وتضم العديد من المواقع المقدسة.','["الاهميه","الدينيه","لموقع","قاره","اسيا","تفسر","اهميتها","تعد","مهد","الديانات","السماويه","اليهوديه","والمسيحيه","والاسلام","وتضم","العديد","المواقع","المقدسه"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156204507,1785156204507);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('LsJ8y06wwQuubdpkt01J','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','الأهمية الإستراتيجية لموقع قارة أوروبا بم تفسر اهميتها الاستراتيجيه. تطل على مسطحات مائية وتشرف على ممرات مهمة مثل مضيق جبل طارق ومضيق البوسفور والدردنيل.','["الاهميه","الاستراتيجيه","لموقع","قاره","اوروبا","تفسر","اهميتها","تطل","علي","مسطحات","ماءيه","وتشرف","ممرات","مهمه","مضيق","جبل","طارق","ومضيق","البوسفور","والدردنيل"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156205078,1785156205078);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('O1K8e2TH8DjOjKYhC9lN','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','جبال قارة أوروبا جبال الألب البرانس الألب الدينارية مون بلان. تمتد سلسلة جبال الألب ويختلف اسمها مثل البرانس (بين فرنسا وإسبانيا) والدينارية (في البلقان)، وبها قمة مون بلان (4800م).','["جبال","قاره","اوروبا","الالب","البرانس","الديناريه","مون","بلان","تمتد","سلسله","ويختلف","اسمها","فرنسا","واسبانيا","والديناريه","البلقان","وبها","قمه","4800م"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156205663,1785156205663);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('Ob5qOg6RrOAL1czmwBjs','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','يختلف اتساع السهول الساحلية من منطقة لأخرى بم تفسر. يختلف الاتساع بسبب اقتراب أو ابتعاد المرتفعات من المسطحات المائية.','["يختلف","اتساع","السهول","الساحليه","منطقه","لاخري","تفسر","الاتساع","بسبب","اقتراب","ابتعاد","المرتفعات","المسطحات","الماءيه"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156206809,1785156206809);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('PR7VwjVUDL4GUL7WLKF6','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','هضاب قارة أوروبا فرنسا الوسطى الميزيتا. يوجد بها عدد قليل من الهضاب مثل هضبة فرنسا الوسطى في فرنسا، وهضبة الميزيتا في إسبانيا.','["هضاب","قاره","اوروبا","فرنسا","الوسطي","الميزيتا","يوجد","بها","عدد","قليل","الهضاب","هضبه","فرنسا،","وهضبه","اسبانيا"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156205997,1785156205997);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('QwwAN28kaBaXLTBJPZ4s','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','ما هو مصطلح أوراسيا يعني ايه المقصود بمصطلح اوراسيا. هو مُصطلح يطلق على قارتي آسيا وأوروبا معًا، نتيجة لظهور قارة أوروبا كأنها امتداد طبيعي لقارة آسيا من جهة الغرب.','["مصطلح","اوراسيا","يعني","ايه","المقصود","بمصطلح","مُصطلح","يطلق","علي","قارتي","اسيا","واوروبا","معًا،","نتيجه","لظهور","قاره","اوروبا","كانها","امتداد","طبيعي","لقاره","جهه","الغرب"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156203333,1785156203333);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('SfBWRkcm6nsAhrBf9yXy','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','هضاب قارة آسيا هضبة التبت الدكن شبه الجزيرة العربية. هضبة التبت في الوسط وهي أعلى هضبة، وهضبة الدكن جنوباً في الهند، وهضبة شبه الجزيرة العربية غرباً.','["هضاب","قاره","اسيا","هضبه","التبت","الدكن","شبه","الجزيره","العربيه","الوسط","وهي","اعلي","هضبه،","وهضبه","جنوباً","الهند،","غرباً"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156205777,1785156205777);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('Ub6dAKZgvaAEiGgUDKg2','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','"ممكن تشرح الفرق بين الطقس والمناخ؟", "الطقس والمناخ ايه الفرق؟", "اي الفرق بين المناخ والطقس؟", "ما الفرق بين المناخ والطقس؟", "قارن بين المناخ والطقس.", "الفرق بين المناخ والطقس في الدراسات.", "سؤال الفرق بين الطقس والمناخ.", "هو الطقس زي المناخ؟", "يعني ايه طقس ويعني ايه مناخ؟", "المناخ والطقس مش فاهمهم.", "وضحلي الفرق بين الطقس والمناخ.",','["ممكن","تشرح","الفرق","الطقس","والمناخ؟","والمناخ","ايه","الفرق؟","المناخ","والطقس؟","قارن","والطقس","الدراسات","سءال","المناخ؟","يعني","طقس","ويعني","مناخ؟","فاهمهم","وضحلي"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027 - (برمجيات)','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785166908195,1785166908195);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('Ucz5Cjm6Kw674Rp6XnhS','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','"الطقس والمناخ فرقهم ايه؟", "ايه الاختلاف بين الطقس والمناخ؟", "فرق الطقس عن المناخ.", "الطقس والمناخ في الجغرافيا.", "اشرحلي الطقس والمناخ.", "الفرق بين الطقس والمناخ باختصار.", "ايه هو الطقس", "ايه هو المناخ", "تعريف الطقس", "تعريف المناخ", "الطقس والمناخ يفرقو ايه عن بعض", "شرح درس الطقس والمناخ", "الطقس والمناخ والفرق بينهم", "يعني اي طقس",','["الطقس","والمناخ","فرقهم","ايه؟","ايه","الاختلاف","والمناخ؟","فرق","المناخ","الجغرافيا","اشرحلي","الفرق","باختصار","تعريف","يفرقو","شرح","درس","والفرق","بينهم","يعني","طقس"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027 - (برمجيات)','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785166908385,1785166908385);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('VEVrnRKEDpLN8sy1ZW7a','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','الأهمية الاقتصادية لموقع قارة آسيا بم تفسر اهميتها الاقتصاديه. تُمثَّل مَعبَرًا رئيسيا لطرق التجارة البرية والبحرية القديمة مثل طريق الحرير وطريق التوابل.','["الاهميه","الاقتصاديه","لموقع","قاره","اسيا","تفسر","اهميتها","تُمثَّل","مَعبَرًا","رءيسيا","لطرق","التجاره","البريه","والبحريه","القديمه","طريق","الحرير","وطريق","التوابل"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156204257,1785156204257);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('VF9x5BHR2d06bGpGKJhX','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','الموقع الفلكي لقارة أوروبا دوائر العرض خطوط الطول. تمتد بين دائرتي 36 و 71 شمالا، ومن خط طول 66 شرقا حتى 25 غربا، ويمر بها خط الطول الرئيسي جرينتش.','["الموقع","الفلكي","لقاره","اوروبا","دواءر","العرض","خطوط","الطول","تمتد","داءرتي","شمالا،","ومن","طول","شرقا","حتي","غربا،","ويمر","بها","الرءيسي","جرينتش"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156204632,1785156204632);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('WKhGpt9ZpmNOWbWnji93','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','مضيق جبل طارق تقترب قارة أوروبا من قارة إفريقيا فين. تقترب قارة أوروبا من قارة إفريقيا عند مضيق جبل طارق.','["مضيق","جبل","طارق","تقترب","قاره","اوروبا","افريقيا","فين"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156204979,1785156204979);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('ae1NU0fS4tytk1CvGt2J','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','الجبال التي تفصل قارة آسيا عن قارة أوروبا. جبال أورال هي الجبال التي تفصل قارة آسيا عن قارة أوروبا.','["الجبال","تفصل","قاره","اسيا","اوروبا","جبال","اورال"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156203926,1785156203926);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('dOM218lulyhPDKX2ZMQt','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','تهديدات تواجه السهول الساحلية التغيرات المناخية التلوث. تواجه السهول الساحلية تهديدات منها التغيرات المناخية، والتلوث، والاستغلال المفرط.','["تهديدات","تواجه","السهول","الساحليه","التغيرات","المناخيه","التلوث","منها","المناخيه،","والتلوث،","والاستغلال","المفرط"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156206929,1785156206929);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('dp0Hyt3JJW2fXliPTkGY','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','الأهمية الإستراتيجية لموقع قارة آسيا بم تفسر اهميتها الاستراتيجيه. تطل على مسطحات مائية مهمة، وتشرف على ممرات ملاحية مثل مضيق باب المندب ومضيق هرمز.','["الاهميه","الاستراتيجيه","لموقع","قاره","اسيا","تفسر","اهميتها","تطل","علي","مسطحات","ماءيه","مهمه،","وتشرف","ممرات","ملاحيه","مضيق","باب","المندب","ومضيق","هرمز"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156204144,1785156204144);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('eMXXqpEXVZX5xSvyK5BF','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','مساحة قارة آسيا مساحتها كام تبلغ قد ايه حجم قارة اسيا. تعد قارة آسيا أكبر قارات العالم من حيث المساحة؛ حيث تبلغ مساحتها نحو 44.2 مليون كم2 (30% من مساحة اليابس).','["مساحه","قاره","اسيا","مساحتها","كام","تبلغ","ايه","حجم","تعد","اكبر","قارات","العالم","حيث","المساحه؛","نحو","مليون","كم2","اليابس"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156203097,1785156203097);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('fFt0Cjqgfy5RmuW4KVx5','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','الموقع الجغرافي لقارة آسيا الحدود المحيطات البحار يحدها ايه. يحدها شمالا المحيط القطبي الشمالي، وجنوبا المحيط الهندي، وشرقا المحيط الهادي، وغربا البحر الأحمر والمتوسط والأسود وجبال أورال.','["الموقع","الجغرافي","لقاره","اسيا","الحدود","المحيطات","البحار","يحدها","ايه","شمالا","المحيط","القطبي","الشمالي،","وجنوبا","الهندي،","وشرقا","الهادي،","وغربا","البحر","الاحمر","والمتوسط","والاسود","وجبال","اورال"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156203802,1785156203802);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('fgz48HHFzulmYI5TAylT','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','مظاهر السطح في قارة آسيا واوروبا. تشغل السلاسل الجبلية والهضاب أكثر من نصف آسيا، بينما أوروبا تتكون من سهول شمالية وجبال جنوبية.','["مظاهر","السطح","قاره","اسيا","واوروبا","تشغل","السلاسل","الجبليه","والهضاب","نصف","اسيا،","بينما","اوروبا","تتكون","سهول","شماليه","وجبال","جنوبيه"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156205437,1785156205437);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('gb2o7dZnElIySuexpXM6','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','الأرخبيل ما المقصود بمعنى مصطلح الأرخبيل. الأرخبيل هو مصطلح يعني مجموعة من الجزر المتجاورة مثل أرخبيل اليابان وإندونيسيا.','["الارخبيل","المقصود","بمعني","مصطلح","يعني","مجموعه","الجزر","المتجاوره","ارخبيل","اليابان","واندونيسيا"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156206584,1785156206584);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('kI7jHGk1hNkK9zYKd7zU','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','سقف العالم بم تفسر تعرف هضبة التبت بسقف العالم. تُعرف هضبة التبت بسقف العالم لأنها أعلى هضبة في العالم.','["سقف","العالم","تفسر","تعرف","هضبه","التبت","بسقف","تُعرف","لانها","اعلي"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156205904,1785156205904);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('kfL9K0KxhUCYumU4kGmz','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','"كيف ساعد نهر النيل على قيام الحضارة؟", "علل أهمية نهر النيل للحضارة المصرية.", "ليه المصريين القدماء عاشوا جنب النيل؟", "سبب قيام الحضارة بجوار النيل؟", "اشرح سبب قيام الحضارة المصرية على النيل.", "لماذا ارتبطت الحضارة المصرية بالنيل؟", "دور نهر النيل في قيام الحضارة المصرية.", "كيف ساهم نهر النيل في نشأة الحضارة؟",','["كيف","ساعد","نهر","النيل","علي","قيام","الحضاره؟","علل","اهميه","للحضاره","المصريه","ليه","المصريين","القدماء","عاشوا","جنب","النيل؟","سبب","الحضاره","بجوار","اشرح","لماذا","ارتبطت","بالنيل؟","دور","ساهم","نشاه"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027 - (برمجيات)','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785166908805,1785166908805);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('ljwmjaHO3BNjNBvUNbtm','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','السهول الفيضية في قارة آسيا أنهار آسيا سيبيريا أوب ينسي لينا اليانجتسي منشوريا دجلة والفرات السند. سهول سيبيريا شمالاً (أوب، ينسي، لينا تتجمد شتاءً)، سهل الصين (اليانجتسي)، سهل منشوريا (أمور)، سهول السند جنوباً، دجلة والفرات غرباً.','["السهول","الفيضيه","قاره","اسيا","انهار","سيبيريا","اوب","ينسي","لينا","اليانجتسي","منشوريا","دجله","والفرات","السند","سهول","شمالاً","اوب،","ينسي،","تتجمد","شتاءً","سهل","الصين","امور","جنوباً،","غرباً"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156206118,1785156206118);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('mECz6kXx6RfWgXPSo2i5','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','الأهمية الحضارية لموقع قارة أوروبا دلل اهميتها الحضاريه الحضارات. قامت بها حضارات قديمة مثل اليونانية والرومانية، والحضارة الأوروبية الحديثة (الثورة العلمية والصناعية).','["الاهميه","الحضاريه","لموقع","قاره","اوروبا","دلل","اهميتها","الحضارات","قامت","بها","حضارات","قديمه","اليونانيه","والرومانيه،","والحضاره","الاوروبيه","الحديثه","الثوره","العلميه","والصناعيه"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156205322,1785156205322);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('meGXqW17dd74GgwYMWEB','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','الأهمية الحضارية لموقع قارة آسيا دلل اهميتها الحضاريه الحضارات القديمة. قامت بها عديد من الحضارات العريقة مثل حضارة بلاد الرافدين، وحضارة فينيقيا، والحضارة الصينية، والهندية، والإسلامية.','["الاهميه","الحضاريه","لموقع","قاره","اسيا","دلل","اهميتها","الحضارات","القديمه","قامت","بها","عديد","العريقه","حضاره","بلاد","الرافدين،","وحضاره","فينيقيا،","والحضاره","الصينيه،","والهنديه،","والاسلاميه"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156204383,1785156204383);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('nu4tbrrAdDSUCLEZZBUN','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','المضايق تقترب قارة آسيا من قارة إفريقيا أوروبا أمريكا الشمالية أستراليا عند مضيق ايه. تقترب من إفريقيا عند مضيق باب المندب، وأوروبا عند مضيقي البوسفور والدردنيل، وأمريكا الشمالية عند مضيق بيرنج، وأستراليا عند بحر تيمور.','["المضايق","تقترب","قاره","اسيا","افريقيا","اوروبا","امريكا","الشماليه","استراليا","مضيق","ايه","باب","المندب،","واوروبا","مضيقي","البوسفور","والدردنيل،","وامريكا","بيرنج،","واستراليا","بحر","تيمور"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156204023,1785156204023);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('qnY8WBxKen45HzOpIzCZ','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','السهول الساحلية في قارة آسيا أطول سواحل خلجان أذرع مائية جزر اليابان إندونيسيا سيريلانكا. تأتي آسيا في المرتبة الأولى بطول سواحلها لاتساعها وكثرة الخلجان، ويوجد جزر مثل سيريلانكا واليابان وإندونيسيا.','["السهول","الساحليه","قاره","اسيا","اطول","سواحل","خلجان","اذرع","ماءيه","جزر","اليابان","اندونيسيا","سيريلانكا","تاتي","المرتبه","الاولي","بطول","سواحلها","لاتساعها","وكثره","الخلجان،","ويوجد","واليابان","واندونيسيا"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156206463,1785156206463);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('tNyUwDZp3jS7MUFhWD1z','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','دوائر العرض الرئيسية في قارة آسيا اللي بتمر فيها. تمر بقارة آسيا الدائرة القطبية الشمالية، ومدار السرطان، ودائرة الاستواء.','["دواءر","العرض","الرءيسيه","قاره","اسيا","اللي","بتمر","فيها","تمر","بقاره","الداءره","القطبيه","الشماليه،","ومدار","السرطان،","وداءره","الاستواء"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156203689,1785156203689);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('u1jd6msXnE75lCdrZbjf','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','ما النتائج المترتبة على امتداد قارة أوروبا بأكملها في النصف الشمالي للكرة الأرضية نتائج الموقع الفلكي لاوروبا. أدى إلى وقوع معظم القارة في المنطقة المناخية المعتدلة الشمالية ويسودها مناخ معتدل بارد عدا الشمال.','["النتاءج","المترتبه","علي","امتداد","قاره","اوروبا","باكملها","النصف","الشمالي","للكره","الارضيه","نتاءج","الموقع","الفلكي","لاوروبا","ادي","الي","وقوع","معظم","القاره","المنطقه","المناخيه","المعتدله","الشماليه","ويسودها","مناخ","معتدل","بارد","عدا","الشمال"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156204751,1785156204751);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('wiLeCHU0Zm78E1LQtqDZ','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','"bot_name": "البوصلة", "core_questions": [ "core_id": "Q_001", "intent": "الطقس_والمناخ", "category": "academic", "answer": "الطقس هو حالة الجو خلال فترة قصيرة، أما المناخ فهو متوسط حالة الجو خلال فترة زمنية طويلة في مكان معين (الطقس = فترة قصيرة، المناخ = فترة طويلة)", "variations": [ "ما الفرق بين الطقس والمناخ؟", "ايه الفرق بين الطقس والمناخ؟",','["bot","name","البوصله","core","questions","001","intent","الطقس","والمناخ","category","academic","answer","حاله","الجو","فتره","قصيره،","اما","المناخ","فهو","متوسط","زمنيه","طويله","مكان","معين","variations","الفرق","والمناخ؟","ايه"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027 - (برمجيات)','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785166907843,1785166907843);
INSERT INTO "lesson_chunks" ("id","course_id","lesson_id","stage","kind","status","text","keywords","grade","unit","subject","source_note","created_at","updated_at") VALUES('zyHEYUyVSD038OCspj01','c1785199571849','lesson_prep2_u1_l1','prep2','شرح','verified','الأهمية الاقتصادية لموقع قارة أوروبا بم تفسر اهميتها الاقتصاديه. ساعد موقعها على سهولة التواصل الاقتصادي مع العالم، وتنوع مناخها أدى لتنوع المحاصيل.','["الاهميه","الاقتصاديه","لموقع","قاره","اوروبا","تفسر","اهميتها","ساعد","موقعها","علي","سهوله","التواصل","الاقتصادي","العالم،","وتنوع","مناخها","ادي","لتنوع","المحاصيل"]','الثاني الإعدادي','الدرس الأول - الوحدة الأولى - الترم الأول - السنة الدراسية 2026/2027','دراسات اجتماعية','مهاجر من القاعدة السابقة: تانية إعدادي - الوحدة الأولى - الدرس الأول',1785156205208,1785156205208);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('0QkqwUoE0QC26ERTxDwu','سؤال الطالب: ده مش منهجي ي فالح إجابة البوصلة: يا رؤى، آسف إن الأسئلة اللي قدمتها مش منهجية أو مش عاجبك أنا هنا عشان أساعدك وتعلم معايا لو عايز، ممكن نبدأ من جديد ونعمل اختبار تاني على الدرس الأول، وناخد الأسئلة من المنهج اللي بتدرسه أو ممكن نناقش موضوع معين في الدرس الأول، ونتكلم عنه إيه اللي تحب تعمله؟','["سءال","الطالب","منهجي","فالح","اجابه","البوصله","رءي،","اسف","الاسءله","اللي","قدمتها","منهجيه","عاجبك","هنا","عشان","اساعدك","وتعلم","معايا","عايز،","ممكن","نبدا","جديد","ونعمل","اختبار","تاني","علي","الدرس","الاول،","وناخد","المنهج","بتدرسه","نناقش","موضوع","معين","ونتكلم","عنه","ايه","تحب","تعمله؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785754714373);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('0cVH0bE0gpwDs8CFiZKe','سؤال الطالب: حصص اليوتيوب اللايف مجانية ام باشتراك إجابة البوصلة: أنا آسف على الارتباك، الحصص اللايف على قناة [قناة الأستاذ يوسف بركات](الرابط) على اليوتيوب هي مجانية، وممكن تتابعها بدون أي اشتراك لكن إذا كنت بتدور على حصص مسجلة أو مواد إضافية، ممكن يكون في خيار للاشتراك في المنصة لتحصل على المزيد من المواد التعليمية.','["سءال","الطالب","حصص","اليوتيوب","اللايف","مجانيه","باشتراك","اجابه","البوصله","اسف","علي","الارتباك،","الحصص","قناه","الاستاذ","يوسف","بركات","الرابط","مجانيه،","وممكن","تتابعها","بدون","اشتراك","كنت","بتدور","مسجله","مواد","اضافيه،","ممكن","يكون","خيار","للاشتراك","المنصه","لتحصل","المزيد","المواد","التعليميه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786048639858);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('0pLfZWNFK76u4kslYHTF','أو تروح لقناة اليوتيوب بتاعته [قناة الأستاذ يوسف بركات](https://www.youtube.com/@youssefbarakat) أو صفحته على الفيسبوك [صفحة الأستاذ يوسف بركات](https://www.facebook.com/youssefbarakatofficial/).','["تروح","لقناه","اليوتيوب","بتاعته","قناه","الاستاذ","يوسف","بركات","https","www","youtube","com","youssefbarakat","صفحته","علي","الفيسبوك","صفحه","facebook","youssefbarakatofficial"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785343787472);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('14OWqPRFghTwtGs9Ds31','ولو عايز تلاقي حاجة على اليوتيوب، ممكن تزور [قناة الأستاذ يوسف بركات](https://www.youtube.com/@youssefbarakat) أو تلاقينا على [صفحة الفيسبوك](https://www.facebook.com/youssefbarakatofficial/) أو حتى تتواصل معنا على [الواتساب](https://wa.me/201023675235) مع السلامة يا رؤى.','["ولو","عايز","تلاقي","حاجه","علي","اليوتيوب،","ممكن","تزور","قناه","الاستاذ","يوسف","بركات","https","www","youtube","com","youssefbarakat","تلاقينا","صفحه","الفيسبوك","facebook","youssefbarakatofficial","حتي","تتواصل","معنا","الواتساب","201023675235","السلامه","رءي"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785754466091);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('1QK8Aig1MUnw9aaPzg7t','سؤال الطالب: ازايك يا غالي إجابة البوصلة: يا حساب، أنا كويس الحمد لله، شكراً على السؤال أنا هنا عشان أساعدك في أي شيء تحتاجه في المنصة، فلو عندك أي سؤال أو استفسار، ما تترددش في السؤال.','["سءال","الطالب","ازايك","غالي","اجابه","البوصله","حساب،","كويس","الحمد","لله،","شكراً","علي","السءال","هنا","عشان","اساعدك","شيء","تحتاجه","المنصه،","فلو","عندك","استفسار،","تترددش"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785367457589);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('1f0rvWsc5oaoF8e6VHPz','سؤال الطالب: انا كنت اعمل ايميل ومش عارف ارجع له إجابة البوصلة: حسناً لو كنت مش عارف ترجع لصفحة الإيميل بتاعتك، ممكن تساعدني أكتر مثلاً، إزاي كنت دخلت الإيميل في الأول وكنت عملت إيه قبل ما تفقد الوصول وأنا أقدر أساعدك كمان لو كنت محتاج تعرف ازاي ترد على الإيميل أو تنجز مهمة معينة عليه بس أولاً، لازم نضمن إنك تقدر ترد لصفحة الإيميل بتاعتك بأمان','["سءال","الطالب","كنت","اعمل","ايميل","ومش","عارف","ارجع","اجابه","البوصله","حسناً","ترجع","لصفحه","الايميل","بتاعتك،","ممكن","تساعدني","اكتر","مثلاً،","ازاي","دخلت","الاول","وكنت","عملت","ايه","تفقد","الوصول","وانا","اقدر","اساعدك","كمان","محتاج","تعرف","ترد","علي","تنجز","مهمه","معينه","عليه","اولاً،","لازم","نضمن","انك","تقدر","بتاعتك","بامان"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785588852608);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('27RwS5ntJFnWGqml1Ygk','سؤال الطالب: برفع الطلب مش بيتقبل إجابة البوصلة: يا حساب، ممكن تكون هناك مشكلة في الإتصال أو في البيانات اللي انت بتسجلها جرب تتحقق من كل حاجة وتأكد إن كل حاجة صح، ثم جرب ترفع الطلب تاني لو لسه مش بيتقبل، ممكن نتواصل مع الدعم الفني عشان يساعدنا نحل المشكلة.','["سءال","الطالب","برفع","الطلب","بيتقبل","اجابه","البوصله","حساب،","ممكن","تكون","هناك","مشكله","الاتصال","البيانات","اللي","بتسجلها","جرب","تتحقق","حاجه","وتاكد","صح،","ترفع","تاني","لسه","بيتقبل،","نتواصل","الدعم","الفني","عشان","يساعدنا","نحل","المشكله"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786015247156);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('2AkZhrE2I4vSHWgPp6HX','سؤال الطالب: مش عارفه ازاي اداني صفر في الامتحان وانا مخرجرش من الامتحان اصلا إجابة البوصلة: يا مريم، أنا فهمت إنك قلقانه عن الامتحان، لكن لازم تهدئي وتفكري إنك لسه لم تخرجي من الامتحان، وده يعني إنك لسه مش عارفة نتيجتك خلي بالك، الامتحانات دي عشان نقيس مستواك، وانا هنا عشان أساعدك تتقوي مستواك، فلا تقلقي، ولو احتجتي لأي مساعدة أو شرح، أنا موجود.','["سءال","الطالب","عارفه","ازاي","اداني","صفر","الامتحان","وانا","مخرجرش","اصلا","اجابه","البوصله","مريم،","فهمت","انك","قلقانه","الامتحان،","لازم","تهدءي","وتفكري","لسه","تخرجي","وده","يعني","نتيجتك","خلي","بالك،","الامتحانات","عشان","نقيس","مستواك،","هنا","اساعدك","تتقوي","فلا","تقلقي،","ولو","احتجتي","لاي","مساعده","شرح،","موجود"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786053382121);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('2DkVgN1gIyyiSFUG9a1G','سؤال الطالب: اتفضل إجابة البوصلة: يا رؤى، ممكن تساعدني أتعرف أكتر عن إحتياجاتك إنت مشترك في الكورسات دي، وانا هنا عشان أساعدك إيه اللي بتحب تعرفه أو تتعلمه أو لو عايز، ممكن نتكلم عن المنصة دي، وأنا أشرحلك مميزاتها المنصة دي أسرع منصة تعليمية، وبتقدم شرح مبسط، وبتوفر متابعة مستمرة كمان، صاحب المنصة الأستاذ يوسف بركات بيقدم شرح مبسط وواضح','["سءال","الطالب","اتفضل","اجابه","البوصله","رءي،","ممكن","تساعدني","اتعرف","اكتر","احتياجاتك","مشترك","الكورسات","دي،","وانا","هنا","عشان","اساعدك","ايه","اللي","بتحب","تعرفه","تتعلمه","عايز،","نتكلم","المنصه","اشرحلك","مميزاتها","اسرع","منصه","تعليميه،","وبتقدم","شرح","مبسط،","وبتوفر","متابعه","مستمره","كمان،","صاحب","الاستاذ","يوسف","بركات","بيقدم","مبسط","وواضح"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785754741949);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('2NM0TLVJ0qZKT40PHTLM','سؤال الطالب: جغرافيا إجابة البوصلة: في الجغرافيا، مصطلح "أوراسيا" يُستخدم لوصف القارة التي تضم أوروبا وآسيا معًا أوراسيا هي أكبر قارة في العالم، وتشمل معظم أراضي أوروبا وآسيا، وتتضمن العديد من البلدان والثقافات المختلفة تُعتبر أوراسيا قارة واحدة من حيث الجغرافيا، ولكنها تُقسم إلى قسمين منفصلين من حيث الثقافة والتاريخ: أوروبا وآسيا','["سءال","الطالب","جغرافيا","اجابه","البوصله","الجغرافيا،","مصطلح","اوراسيا","يُستخدم","لوصف","القاره","تضم","اوروبا","واسيا","معًا","اكبر","قاره","العالم،","وتشمل","معظم","اراضي","واسيا،","وتتضمن","العديد","البلدان","والثقافات","المختلفه","تُعتبر","واحده","حيث","ولكنها","تُقسم","الي","قسمين","منفصلين","الثقافه","والتاريخ"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785162129908);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('2WIRCIBLrZBRZZEJG43K','و لو محتاج تتواصل مع الإدارة، يمكنك التحدث معهم على رقم 01023675235.','["محتاج","تتواصل","الاداره،","يمكنك","التحدث","معهم","علي","رقم","01023675235"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785443356030);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('2iDZevbpeZPmr0VUPQmn','سؤال الطالب: ايوا إجابة البوصلة: أوراسيا تضم العديد من الجبال والسهول والبحار والأنهار، وتتميز بتنوع كبير في مناخها وطبيعتها بعض من أهم ميزات أوراسيا الجغرافية تشمل: * جبال الهيمالايا، التي هي أعلى سلسلة جبلية في العالم * سهول أوروبا الشرقية، التي هي واحدة من أكبر السهول في العالم * بحر قزوين، الذي هو أكبر بحر مغلق في العالم','["سءال","الطالب","ايوا","اجابه","البوصله","اوراسيا","تضم","العديد","الجبال","والسهول","والبحار","والانهار،","وتتميز","بتنوع","كبير","مناخها","وطبيعتها","اهم","ميزات","الجغرافيه","تشمل","جبال","الهيمالايا،","اعلي","سلسله","جبليه","العالم","سهول","اوروبا","الشرقيه،","واحده","اكبر","السهول","بحر","قزوين،","مغلق"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785162152976);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('2pVjqvEFL1y3NcXelITy','إذا كنت تريد أن نبدأ من جديد أو تريد أن أساعدك في شيء معين، أنا هنا لخدمتك لا داعي للبرمجة أو التغيير، أنا جاهز للاستمرار في المساعدة بشكل طبيعي.','["كنت","تريد","نبدا","جديد","اساعدك","شيء","معين،","هنا","لخدمتك","داعي","للبرمجه","التغيير،","جاهز","للاستمرار","المساعده","بشكل","طبيعي"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785359745908);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('2sxzm8KDuvUCQkXTEqVN','سؤال الطالب: مش  عارفةة أجيب الامتحان بعد المحاضرة الاولي إجابة البوصلة: لا تقلقي، الامتحانات دي عشان نقيس مستواك جربي تحلّي بنفسك ولو وقفتي في فهم نقطة معينة أنا هنا أشرحلك من عيني محاضرة أولى مش كتير، هتلاقي وقت كفاية لتدرّبي وتفهمي المادة قبل الامتحان إنتي قوية وقادرة!','["سءال","الطالب","عارفهه","اجيب","الامتحان","المحاضره","الاولي","اجابه","البوصله","تقلقي،","الامتحانات","عشان","نقيس","مستواك","جربي","تحلّي","بنفسك","ولو","وقفتي","فهم","نقطه","معينه","هنا","اشرحلك","عيني","محاضره","اولي","كتير،","هتلاقي","وقت","كفايه","لتدرّبي","وتفهمي","الماده","انتي","قويه","وقادره"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786690831145);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('3FrQAkgxYGNaU43L2T12','سؤال الطالب: ابعت صفحة الفيس إجابة البوصلة: [صفحة الفيسبوك](https://www.facebook.com/youssefbarakatofficial/)','["سءال","الطالب","ابعت","صفحه","الفيس","اجابه","البوصله","الفيسبوك","https","www","facebook","com","youssefbarakatofficial"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785170183731);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('3Pb5jq1tuoW3GLz1d4Uc','إجابة البوصلة: يا أيه، شكراً جداً على كلامك الجميل، نحن سعداء جداً أننا نستطيع مساعدتك وخدمتك، ونتمنى لك التوفيق والنجاح في دراستك، وإن شاء الله نكون قد ساهموا في مساعدتك لتحقيق أهدافك، وبارك الله فيك على دعائك الجميل، ونحن دائماً هنا لخدمتك ونساعدك في أي شيء محتاج له، فلا تتردد في التواصل معنا في أي وقت 🙏','["اجابه","البوصله","ايه،","شكراً","جداً","علي","كلامك","الجميل،","سعداء","اننا","نستطيع","مساعدتك","وخدمتك،","ونتمني","التوفيق","والنجاح","دراستك،","وان","شاء","الله","نكون","ساهموا","لتحقيق","اهدافك،","وبارك","فيك","دعاءك","ونحن","داءماً","هنا","لخدمتك","ونساعدك","شيء","محتاج","له،","فلا","تتردد","التواصل","معنا","وقت"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785950070215);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('3aeeew0AkJXcwphfAM9L','سؤال الطالب: طيب إجابة البوصلة: يا حساب، طيب في حاجة جديدة عايز تسأل عنها أو في حاجة محتاج مساعدة فيها أنا هنا لسانديك.','["سءال","الطالب","طيب","اجابه","البوصله","حساب،","حاجه","جديده","عايز","تسال","عنها","محتاج","مساعده","فيها","هنا","لسانديك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786121109674);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('3eGqDjJMfZwXIBFiGalQ','سؤال الطالب: ايوه انا عايزاها هنا على القناه إجابة البوصلة: يا جنى، أنا فهمت، لكن المنصة مش بتقدم محاضرات سابقة هنا، لكن لو عايزة أساعدك في فهم نقطة معينة أو أسألة معينة، أنا موجود هنا لأساعدك.','["سءال","الطالب","ايوه","عايزاها","هنا","علي","القناه","اجابه","البوصله","جني،","فهمت،","المنصه","بتقدم","محاضرات","سابقه","هنا،","عايزه","اساعدك","فهم","نقطه","معينه","اساله","معينه،","موجود","لاساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786619675304);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('3g3SGAEsSJp0CMQHEbtY','[الواتساب](https://wa.me/201023675235) أو إذا كنت تريد التحدث مع الإدارة، ممكن تتصل على رقم: 01023675235','["الواتساب","https","201023675235","كنت","تريد","التحدث","الاداره،","ممكن","تتصل","علي","رقم","01023675235"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785410093082);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('3r6V7ULggXbf7qUBjar4','سؤال الطالب: لا قشطه شكرا إجابة البوصلة: على الرحب والسعة يا جنى، لو احتجتي لأي حاجة تانية، متخافيش تقولي.','["سءال","الطالب","قشطه","شكرا","اجابه","البوصله","علي","الرحب","والسعه","جني،","احتجتي","لاي","حاجه","تانيه،","متخافيش","تقولي"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786619702023);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('3u57AtLhf3UVTuBAplGk','سؤال الطالب: يعني ليه خمس دقائق بس إجابة البوصلة: يا أيه، أنا فهمت، أنت بتقول إن التدريب اللي بيكون في خمس دقائق بس، ده عشان نضمن إنك بتحل التدريب بسرعة وبدون مبالغة في الوقت، وده جزء من سياسة المنصة لتحفيز الطلاب على الحل السريع والدقيق، وده بيخليك تحسن مهاراتك في الحل السريع والتركيز.','["سءال","الطالب","يعني","ليه","خمس","دقاءق","اجابه","البوصله","ايه،","فهمت،","بتقول","التدريب","اللي","بيكون","بس،","عشان","نضمن","انك","بتحل","بسرعه","وبدون","مبالغه","الوقت،","وده","جزء","سياسه","المنصه","لتحفيز","الطلاب","علي","الحل","السريع","والدقيق،","بيخليك","تحسن","مهاراتك","والتركيز"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786205562182);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('3v5KtoLkSwHxm5kZDGls','سؤال الطالب: أنا مش عارفه احل السوال ده اجابتي كانت بتقول أنو القاره القطبيه الجنوبيه المتجمدة صح ولا غلط إجابة البوصلة: يا أيه، القارة القطبية الجنوبية هي جزء من العالم الجديد، وبالتالي إجابتك صحيحة القارات في العالم الجديد هي أمريكا الشمالية، أمريكا الجنوبية، و القارة القطبية الجنوبية أنت حلتي السؤال بشكل صحيح.','["سءال","الطالب","عارفه","احل","السوال","اجابتي","بتقول","انو","القاره","القطبيه","الجنوبيه","المتجمده","ولا","غلط","اجابه","البوصله","ايه،","جزء","العالم","الجديد،","وبالتالي","اجابتك","صحيحه","القارات","الجديد","امريكا","الشماليه،","الجنوبيه،","حلتي","السءال","بشكل","صحيح"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785443158849);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('4RvoefTLCd6sCgHAMxFX','سؤال الطالب: ابعت شكوتي للمستر بشتكي إنك كتابتك سيئة بحس إنك سئ مش بتعرف تكتب عربي إجابة البوصلة: حسناً، سأرسل شكوتك إلى المستر يوسف بركات لكن قبل ذلك، أريد أن أقول إنني آسف إذا كانت كتابتي لم تكن على مستوى التوقعات أنا أحاول دائماً أن أكتب بالعربية بطريقة واضحة ومفهومة، ولكن أحياناً قد أ_commit أخطاء','["سءال","الطالب","ابعت","شكوتي","للمستر","بشتكي","انك","كتابتك","سيءه","بحس","بتعرف","تكتب","عربي","اجابه","البوصله","حسناً،","سارسل","شكوتك","الي","المستر","يوسف","بركات","ذلك،","اريد","اقول","انني","اسف","كتابتي","تكن","علي","مستوي","التوقعات","احاول","داءماً","اكتب","بالعربيه","بطريقه","واضحه","ومفهومه،","ولكن","احياناً","commit","اخطاء"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785181490962);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('4w0glZyuCgyMJRlg81RF','سؤال الطالب: شكرًا إجابة البوصلة: على الرحب والسعة إذا كنت تحتاج إلى أي مساعدة أخرى أو لديك أسئلة أخرى، لا تتردد في السؤال يمكنك أيضًا زيارة [قناة الأستاذ يوسف بركات](https://www.youtube.com/@youssefbarakat) على اليوتيوب أو [صفحة الأستاذ يوسف بركات](https://www.facebook.com/youseffbarkat) على الفيسبوك للحصول على مزيد من المعلومات والموارد التعليمية','["سءال","الطالب","شكرًا","اجابه","البوصله","علي","الرحب","والسعه","كنت","تحتاج","الي","مساعده","اخري","لديك","اسءله","اخري،","تتردد","السءال","يمكنك","ايضًا","زياره","قناه","الاستاذ","يوسف","بركات","https","www","youtube","com","youssefbarakat","اليوتيوب","صفحه","facebook","youseffbarkat","الفيسبوك","للحصول","مزيد","المعلومات","والموارد","التعليميه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785162217580);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('4ymXT9W7NXY0cG8XC1vG','سؤال الطالب: لاتنين إجابة البوصلة: يا إكرام، عشان تدخل الكورسات، أولاً لازم تدخل على المنصة بتاعتنا، وبعدين تلاقي تبويب اسمه ''كورساتي''، وهناك هتلاقي كود الكورس اللي انت مشترك فيه، وهو c1785241200444','["سءال","الطالب","لاتنين","اجابه","البوصله","اكرام،","عشان","تدخل","الكورسات،","اولاً","لازم","علي","المنصه","بتاعتنا،","وبعدين","تلاقي","تبويب","اسمه","كورساتي","وهناك","هتلاقي","كود","الكورس","اللي","مشترك","فيه،","وهو","c1785241200444"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785496927818);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('58JZSKmXsvCJn2OAKSwK','سؤال الطالب: السلام عليكم ورحمه والله وبركاته لو سمحت هو ينفع احل الامتحان في وقت تاني غير الساعه 9','["سءال","الطالب","السلام","عليكم","ورحمه","والله","وبركاته","سمحت","ينفع","احل","الامتحان","وقت","تاني","الساعه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785949829502);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('5KZxawgvwxVzobvD6i2l','سؤال الطالب: ازايك إجابة البوصلة: أنا كويسة شكرا، وأتمنى أنك كمان تكون زين يوسف بركات هو صاحب المنصة التعليمية اللي أنتا مشترك فيها، وهو بيقدم شرح مبسط ومتابعة مستمرة للمواد الدراسية لو عندك أي أسئلة أو محتاج مساعدة في أي حاجة، أنا هنا لساندها.','["سءال","الطالب","ازايك","اجابه","البوصله","كويسه","شكرا،","واتمني","انك","كمان","تكون","زين","يوسف","بركات","صاحب","المنصه","التعليميه","اللي","انتا","مشترك","فيها،","وهو","بيقدم","شرح","مبسط","ومتابعه","مستمره","للمواد","الدراسيه","عندك","اسءله","محتاج","مساعده","حاجه،","هنا","لساندها"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785203383525);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('5aGQeawCjxSupwv4PC3c','سؤال الطالب: بقولك مين هو يوسف بركات إجابة البوصلة: أستاذ يوسف بركات هو صاحب منصة تعليمية رائعة لتعليم الدراسات الاجتماعية للمرحلة الإعدادية والثانوية بمصر هو بيعمل جهد كبير عشان يوفر لنا شرح مبسط وممتع للمادة، وبيساعدنا نتعلم بأفضل طريقة','["سءال","الطالب","بقولك","مين","يوسف","بركات","اجابه","البوصله","استاذ","صاحب","منصه","تعليميه","راءعه","لتعليم","الدراسات","الاجتماعيه","للمرحله","الاعداديه","والثانويه","بمصر","بيعمل","جهد","كبير","عشان","يوفر","لنا","شرح","مبسط","وممتع","للماده،","وبيساعدنا","نتعلم","بافضل","طريقه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785169473010);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('5v7kIejmpwCAmApW3pxV','سؤال الطالب: حالل كله صح وعملي١٠٠% وبعد كده قالي لقد حصلت علي ٠%ليه مع اني انا متأكد اني انا حليت صح إجابة البوصلة: يا يوسف، ممكن يكون هناك خطأ تقني في النظام أو في تسجيل الإجابات أتمنى أنك تتواصل مع الدعم الفني على رقم ٠١٠٢٣٦٧٥٢٣٥ عشان يفحصوا القضية ويحلوها لك.','["سءال","الطالب","حالل","كله","وعملي١٠٠","وبعد","كده","قالي","لقد","حصلت","علي","ليه","اني","متاكد","حليت","اجابه","البوصله","يوسف،","ممكن","يكون","هناك","خطا","تقني","النظام","تسجيل","الاجابات","اتمني","انك","تتواصل","الدعم","الفني","رقم","٠١٠٢٣٦٧٥٢٣٥","عشان","يفحصوا","القضيه","ويحلوها"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786060545132);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('65clKz2w8s8T8sUTKUeO','إجابة البوصلة: لا، مش ضروري تكتب رقم الموبايل، بس لو محتاج تتكلم مع الإدارة، تقدر تتواصل مع الأستاذ يوسف بركات على [رقم الدعم الفني](https://wa.me/201023675235) أو تروح لقناة اليوتيوب [قناة الأستاذ يوسف بركات](https://www.youtube.com/@youssefbarakat) أو صفحة الفيسبوك [صفحة الأستاذ يوسف بركات](https://www.facebook.com/youssefbarakatofficial/)','["اجابه","البوصله","لا،","ضروري","تكتب","رقم","الموبايل،","محتاج","تتكلم","الاداره،","تقدر","تتواصل","الاستاذ","يوسف","بركات","علي","الدعم","الفني","https","201023675235","تروح","لقناه","اليوتيوب","قناه","www","youtube","com","youssefbarakat","صفحه","الفيسبوك","facebook","youssefbarakatofficial"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785404003432);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('6JK78e4TzrM4A1PPtNrP','سؤال الطالب: عرفت اسمي منيم إجابة البوصلة: يا هنا، عرفت اسمك من المعلومات اللي معايا، لأنك سجلت في الكورسات بتاعتنا، واسمك هنا محمد محمد عبد المطلب، ورقم هاتفك 01227870971، وكمان رقم الكورس اللي أنت مشترك فيه هو c1785241200444 أتمنى أكون ساعدتك في أي حاجة تانية!','["سءال","الطالب","عرفت","اسمي","منيم","اجابه","البوصله","هنا،","اسمك","المعلومات","اللي","معايا،","لانك","سجلت","الكورسات","بتاعتنا،","واسمك","هنا","محمد","عبد","المطلب،","ورقم","هاتفك","01227870971،","وكمان","رقم","الكورس","مشترك","فيه","c1785241200444","اتمني","اكون","ساعدتك","حاجه","تانيه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786052198398);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('6LyeRkNmBuAk8wy1x8SW','لو عايز تسأل عن أي حاجة تانية، أو تريد مساعدة في حل تمرين، أنا هنا عشان أجاوب عليك ولو محتاج تتواصل مع الإدارة، ممكن تتصل على [رقم الدعم الفني](01023675235) أو تvisit [قناة اليوتيوب](https://www.youtube.com/@youssefbarakat) أو [صفحة الفيسبوك](https://www.facebook.com/youssefbarakatofficial/) أو [الواتساب](https://wa.me/201023675235).','["عايز","تسال","حاجه","تانيه،","تريد","مساعده","تمرين،","هنا","عشان","اجاوب","عليك","ولو","محتاج","تتواصل","الاداره،","ممكن","تتصل","علي","رقم","الدعم","الفني","01023675235","تvisit","قناه","اليوتيوب","https","www","youtube","com","youssefbarakat","صفحه","الفيسبوك","facebook","youssefbarakatofficial","الواتساب","201023675235"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785755117486);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('6WfQv5ebSvD5ua8UhzQy','سؤال الطالب: انا عامل حساب ومش عارف نجيبه إجابة البوصلة: حسناً أنا هنا لمساعدتك لكن أولاً، أتأكد إنك مش بتسأل عن حل سؤال امتحان مباشرة لأننا هنا بنساعد في فهم المفاهيم والشرح، مش في الغش أو الحلول السريعة لو كنت محتاج مساعدة في فهم نقطة معينة أو شرح مفصل، أنا موجود لمساعدتك قُل لي أكثر عن الحساب اللي مش عارف تنجيه، وأنا هساعدك إن شاء الله!','["سءال","الطالب","عامل","حساب","ومش","عارف","نجيبه","اجابه","البوصله","حسناً","هنا","لمساعدتك","اولاً،","اتاكد","انك","بتسال","امتحان","مباشره","لاننا","بنساعد","فهم","المفاهيم","والشرح،","الغش","الحلول","السريعه","كنت","محتاج","مساعده","نقطه","معينه","شرح","مفصل،","موجود","قُل","الحساب","اللي","تنجيه،","وانا","هساعدك","شاء","الله"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785588804995);
