INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('8Fh2m03PzVOIsl1DDQpV','إجابة البوصلة: يا أيه، المحاضرة التعريفية بتبقى في بداية الكورس، وبيتناول فيها الأستاذ يوسف بركات موضوعات مهمة عن المنصة وطريقة عملها، وبيشرح فيها مميزات المنصة زي أنها أسرع منصة تعليمية، وشرح مبسط، ومتابعة مستمرة، وبيتكلم عن أهمية المتابعة والالتزام بالموعد، وبيmention رقم هاتف الدعم الفني، وبيخليك تعرف كيف تتواصل معنا لو محتاج أي مساعدة، وكمان بيتكلم عن قناة اليوتيوب وصفحة الفيسبوك والواتساب، زي ما في [قناة الأستاذ يوسف بركات](https://www.youtube.com/@youssefbarakat) و [صفحة الفيسبوك](https://www.facebook.com/youssefbarakatofficial/) و [الواتساب](https://wa.me/201023675235) عشان تتابع كل حاجة جديدة، وأخيراً بيتكلم عن أهمية الحفاظ على المفتاح السري والبيانات الشخصية، وبيخليك تعرف إننا هنا عشان نساعدك في أي حاجة، ولو محتاج أي حاجة تانية أتمنى ت告诉ني 🙏','["اجابه","البوصله","ايه،","المحاضره","التعريفيه","بتبقي","بدايه","الكورس،","وبيتناول","فيها","الاستاذ","يوسف","بركات","موضوعات","مهمه","المنصه","وطريقه","عملها،","وبيشرح","مميزات","انها","اسرع","منصه","تعليميه،","وشرح","مبسط،","ومتابعه","مستمره،","وبيتكلم","اهميه","المتابعه","والالتزام","بالموعد،","وبيmention","رقم","هاتف","الدعم","الفني،","وبيخليك","تعرف","كيف","تتواصل","معنا","محتاج","مساعده،","وكمان","بيتكلم","قناه","اليوتيوب","وصفحه","الفيسبوك","والواتساب،","https","www","youtube","com","youssefbarakat","صفحه","facebook","youssefbarakatofficial","الواتساب","201023675235","عشان","تتابع","حاجه","جديده،","واخيراً","الحفاظ","علي","المفتاح","السري","والبيانات","الشخصيه،","اننا","هنا","نساعدك","حاجه،","ولو","تانيه","اتمني"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785949947429);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('9FITaXYf0DVPiLKHGRXl','هو صاحب المنصة التي أنا جزء منها، ويعتبر من أفضل المدرسين في مجال الدراسات الاجتماعية في مصر المستر يوسف بركات لديه أسلوب تعليمي ممتع ومبسط، ويتابع طلابه باستمرار لضمان فهمهم للمادة كما أنه ي提供 دروساً مجانية على قناة اليوتيوب الخاصة به، [قناة الأستاذ يوسف بركات](https://www.youtube.com/@youssefbarakat)','["صاحب","المنصه","جزء","منها،","ويعتبر","افضل","المدرسين","مجال","الدراسات","الاجتماعيه","مصر","المستر","يوسف","بركات","لديه","اسلوب","تعليمي","ممتع","ومبسط،","ويتابع","طلابه","باستمرار","لضمان","فهمهم","للماده","كما","انه","دروساً","مجانيه","علي","قناه","اليوتيوب","الخاصه","به،","الاستاذ","https","www","youtube","com","youssefbarakat"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785202679347);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('9FM2f9L1CCKEy3BDAOov','سؤال الطالب: هو عطاني صفر في درجة الامتحان بس انا مخرجتش من الامتحان إجابة البوصلة: يا مريم، ده مش ممكن، لأنك لسه لم تخرجي من الامتحان، فلازم تنتظري النتيجة بعد ما تخرجي لو عندك أي استفسار أو مشكلة، أنا هنا عشان أساعدك، بس لازم ننتظر النتيجة الرسمية بعد الامتحان.','["سءال","الطالب","عطاني","صفر","درجه","الامتحان","مخرجتش","اجابه","البوصله","مريم،","ممكن،","لانك","لسه","تخرجي","الامتحان،","فلازم","تنتظري","النتيجه","عندك","استفسار","مشكله،","هنا","عشان","اساعدك،","لازم","ننتظر","الرسميه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786053441495);
