INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('EELcl6SsB6DedVo7BaAM','سؤال الطالب: ومتلاقيشها إجابة البوصلة: يا حساب، ممكن تساعدني أكتر إنت مشترك في الكورسات c1785199571849 وc1785241200444، في أي كورس منهم بتحاول تلاقي حاجة محددة عشان أساعدك أستخرجها ليك.','["سءال","الطالب","ومتلاقيشها","اجابه","البوصله","حساب،","ممكن","تساعدني","اكتر","مشترك","الكورسات","c1785199571849","وc1785241200444،","كورس","منهم","بتحاول","تلاقي","حاجه","محدده","عشان","اساعدك","استخرجها","ليك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785869948298);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('EH8Dds6gQnknBwTX3lfp','سؤال الطالب: تاريخ إجابة البوصلة: يا ايتن، في تاريخ العالم الجديد، القارات دي هما أمريكا الشمالية وأمريكا الجنوبية أمريكا الشمالية بتضم دول زي الولايات المتحدة وكندا والمكسيك، بينما أمريكا الجنوبية بتضم دول زي البرازيل والأرجنتين وشيلى تاريخ هذه القارات بيرجع لآلاف السنين، حيث كان سكانها الأصليون هم الشعوب الهندية','["سءال","الطالب","تاريخ","اجابه","البوصله","ايتن،","العالم","الجديد،","القارات","هما","امريكا","الشماليه","وامريكا","الجنوبيه","بتضم","دول","الولايات","المتحده","وكندا","والمكسيك،","بينما","البرازيل","والارجنتين","وشيلي","بيرجع","لالاف","السنين،","حيث","سكانها","الاصليون","الشعوب","الهنديه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785781782169);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('ENwXOel9r8NAHYNQNwGz','أو يمكنك الاتصال بنا مباشرة على رقم 01023675235، وسيقوم الأستاذ يوسف بركات أو فريق الدعم الفني بمساعدتك في عملية الاشتراك منصة الأستاذ يوسف بركات تقدم لك شرحًا مبسطًا ومتابعة مستمرة، وأنا هنا لأساعدك في أي سؤال أو استفسار لديك!','["يمكنك","الاتصال","بنا","مباشره","علي","رقم","01023675235،","وسيقوم","الاستاذ","يوسف","بركات","فريق","الدعم","الفني","بمساعدتك","عمليه","الاشتراك","منصه","تقدم","شرحًا","مبسطًا","ومتابعه","مستمره،","وانا","هنا","لاساعدك","سءال","استفسار","لديك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785586917642);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('Ee8BSkTvrO4y0KW3ad5V','سؤال الطالب: هو انا ليه ظاهر عندي لوحه الشرف ومكتوب اني من افضل الطلاب دي المستر اللي بيبقي عاملها ولا ايه إجابة البوصلة: يا مريم، ده شيء رائع جداً لوحة الشرف دي تعني إنك من الأفضل، وده شيء ليك أنت، مش للمستر أنت اللي بتحقق الدرجات دي واللي بتحصل على التقدير ده المستر بيساعدك وتدريبك، لكن النجاح最終 بيكون ليك','["سءال","الطالب","ليه","ظاهر","عندي","لوحه","الشرف","ومكتوب","اني","افضل","الطلاب","المستر","اللي","بيبقي","عاملها","ولا","ايه","اجابه","البوصله","مريم،","شيء","راءع","جداً","تعني","انك","الافضل،","وده","ليك","انت،","للمستر","بتحقق","الدرجات","واللي","بتحصل","علي","التقدير","بيساعدك","وتدريبك،","النجاح","بيكون"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786392151094);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('EiaZMUP4Z2NurqAWqybx','مثال: جبال روكي في أمريكا الشمالية، جبال الأنديز في أمريكا الجنوبية وأنا هنا إذا احتجت لشرح أو مساعدة أي قارة بدري نبدأ بيها؟','["مثال","جبال","روكي","امريكا","الشماليه،","الانديز","الجنوبيه","وانا","هنا","احتجت","لشرح","مساعده","قاره","بدري","نبدا","بيها؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785203513768);
