INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('FQgVoJyZR2VGy0yMTXGC','سؤال الطالب: تساعدني في كتابة كلمة مرور إجابة البوصلة: معلش، أنا مش عارف أعرف كلمة المرور بتاعتك، لأنها خاصة بيك و مش عندي حق الوصول ليها لكن أنا ممكن أساعدك في إنك تختار كلمة مرور قوية و آمنة كلمة المرور القوية بيكون فيها: * حروف كبيرة و صغيرة * رموز خاصة مثلاً، ممكن تختار كلمة مرور مثل: "Aa123!@#"','["سءال","الطالب","تساعدني","كتابه","كلمه","مرور","اجابه","البوصله","معلش،","عارف","اعرف","المرور","بتاعتك،","لانها","خاصه","بيك","عندي","الوصول","ليها","ممكن","اساعدك","انك","تختار","قويه","امنه","القويه","بيكون","فيها","حروف","كبيره","صغيره","رموز","مثلاً،","aa123"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785409930169);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('FbKC8SigYRFYtHVzeeAl','سؤال الطالب: اعمل اي إجابة البوصلة: يا أيه، الساعة 12 دلوقتي، الامتحان بيفتح الساعة 9 مساءً فقط، فمازال هناك وقت قبل ما يفتح الامتحان، ممكن تتدرب وتستعد للامتحان، أو تدرس أي حاجة تانية، وانا هساعدك في أي حاجة تحتاجها، لو عندك أي أسئلة أو محتاج مساعدة في أي حاجة، قول لي عشان اساعدك','["سءال","الطالب","اعمل","اجابه","البوصله","ايه،","الساعه","دلوقتي،","الامتحان","بيفتح","مساءً","فقط،","فمازال","هناك","وقت","يفتح","الامتحان،","ممكن","تتدرب","وتستعد","للامتحان،","تدرس","حاجه","تانيه،","وانا","هساعدك","تحتاجها،","عندك","اسءله","محتاج","مساعده","حاجه،","قول","عشان","اساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785962927172);
