INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('HxLvbbiO41Oig6Bxdolr','سؤال الطالب: ازاي اجيب المحاضره بعد ما خلصت انا ما حضرتهاش يعني عايز اجيبها إجابة البوصلة: يا جنى، لو محاضرة انتهت، تقدري تلاقيها على قناة الأستاذ يوسف بركات على اليوتيوب [قناة الأستاذ يوسف بركات](الرابط) أو تقدري تسألي عنها هنا وأنا هساعدك.','["سءال","الطالب","ازاي","اجيب","المحاضره","خلصت","حضرتهاش","يعني","عايز","اجيبها","اجابه","البوصله","جني،","محاضره","انتهت،","تقدري","تلاقيها","علي","قناه","الاستاذ","يوسف","بركات","اليوتيوب","الرابط","تسالي","عنها","هنا","وانا","هساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786619639234);
