INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('JDy5J8G5WEb4AL5VpURg','سؤال الطالب: بيقول الامتحان مقفول إجابة البوصلة: يا أيه، ممكن يكون الامتحان لم يفتح بعد أو انتهى الوقت المحدد للامتحان، لأن مواعيد الامتحانات ثابتة، للمرحلة الإعدادية يوم الأربعاء الساعة 9 مساءً، والمرحلة الثانوية يوم الأربعاء الساعة 9 مساءً أيضاً، لو سمحت 告لي ما هي المرحلة التي أنت فيها والموعد الذي حاولت دخول الامتحان فيه','["سءال","الطالب","بيقول","الامتحان","مقفول","اجابه","البوصله","ايه،","ممكن","يكون","يفتح","انتهي","الوقت","المحدد","للامتحان،","لان","مواعيد","الامتحانات","ثابته،","للمرحله","الاعداديه","يوم","الاربعاء","الساعه","مساءً،","والمرحله","الثانويه","مساءً","ايضاً،","سمحت","المرحله","فيها","والموعد","حاولت","دخول","فيه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785962836212);
