INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('KPVFtrj3Sesug4rGzPZt','سؤال الطالب: ده كودي إجابة البوصلة: يا رؤى، شكراً على ثقتك فيّ أنا هستخدم الكود ده عشان أستطيع مساعدتك بشكل أفضل الآن، ممكن نبدأ اختبار أول درس أنا هسألك أسئلة عن الدرس الأول، ونتكلم عن إجاباتك هتكون تجربة ممتعة ومفيدة أو لو عايز تسأل عن أي حاجة تانية، أنا هنا عشان أجاوب عليك.','["سءال","الطالب","كودي","اجابه","البوصله","رءي،","شكراً","علي","ثقتك","فيّ","هستخدم","الكود","عشان","استطيع","مساعدتك","بشكل","افضل","الان،","ممكن","نبدا","اختبار","اول","درس","هسالك","اسءله","الدرس","الاول،","ونتكلم","اجاباتك","هتكون","تجربه","ممتعه","ومفيده","عايز","تسال","حاجه","تانيه،","هنا","اجاوب","عليك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785755105419);
