INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('KnfdG28FgtSlmfb1EEPE','سؤال الطالب: قولي مقاس صورة الكورس كام إجابة البوصلة: معلش، مافيش معلومات واضحة عن مقاس صورة الكورس ممكن توضح أكتر عن الكورس ده أو الصورة اللي بتبحث عنها عشان أستطع أساعدك أفضل.','["سءال","الطالب","قولي","مقاس","صوره","الكورس","كام","اجابه","البوصله","معلش،","مافيش","معلومات","واضحه","ممكن","توضح","اكتر","الصوره","اللي","بتبحث","عنها","عشان","استطع","اساعدك","افضل"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785170487027);
