INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('L2kvVurBhldevnBYMIKi','سؤال الطالب: ها عارف انا مين إجابة البوصلة: أهلاً بيك يا أستاذ يوسف بركات أنا عارف إنك أنت، صاحب المنصة وأستاذ الدراسات الاجتماعية أنا هنا لأساعدك في أي شيء تحتاجه، سواء كان ذلك متعلقًا بالمنصة أو بالطلاب أو بأي شيء آخر ماذا تريد أن تفعل اليوم؟','["سءال","الطالب","عارف","مين","اجابه","البوصله","اهلاً","بيك","استاذ","يوسف","بركات","انك","انت،","صاحب","المنصه","واستاذ","الدراسات","الاجتماعيه","هنا","لاساعدك","شيء","تحتاجه،","سواء","متعلقًا","بالمنصه","بالطلاب","باي","اخر","ماذا","تريد","تفعل","اليوم؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785203365272);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('LO71fHjfYzQhRib6qZbC','سؤال الطالب: جغرفيا إجابة البوصلة: يا ايتن، أول درس في الجغرافيا للصف الثالث الإعدادي بيكون عن مفهوم الجغرافيا واهميته بيتناول الدرس تعريف الجغرافيا، وأهمية دراستها، والفرق بين الجغرافيا الطبيعية والبشرية كمان بيتكلم عن أهمية الجغرافيا في حياتنا اليومية، زي فهم التغيرات المناخية، واستخدام الموارد الطبيعية، وتحديد المواقع الجغرافية','["سءال","الطالب","جغرفيا","اجابه","البوصله","ايتن،","اول","درس","الجغرافيا","للصف","الثالث","الاعدادي","بيكون","مفهوم","واهميته","بيتناول","الدرس","تعريف","الجغرافيا،","واهميه","دراستها،","والفرق","الطبيعيه","والبشريه","كمان","بيتكلم","اهميه","حياتنا","اليوميه،","فهم","التغيرات","المناخيه،","واستخدام","الموارد","الطبيعيه،","وتحديد","المواقع","الجغرافيه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785781754817);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('LRNEZ9RIlYEnpMqJQWJi','إجابة البوصلة: يا أيه، الدرس الأول في الدراسات الاجتماعية بيكون دروس مهم جداً، وبيتناول موضوعات أساسية عن المجتمع والثقافة والبيئة، وبيشرح الأستاذ يوسف بركات كيف ن理解 المجتمع ونحلل العلاقات بين الأفراد والمجتمعات، وبيتكلم عن أهمية الدراسات الاجتماعية في حياتنا اليومية، وبيعرفك على كيفية استخدام المفاهيم والأساليب الاجتماعية لتحليل القضايا المختلفة، وبيخليك تعرف كيف تطور مهاراتك في التفكير النقدي والتحليل، ولو محتاج أي شرح أو توضيح في أي نقطة من الدرس، أنا هنا عشان اساعدك، بس أتمنى ت告诉ني أي جزء من الدرس محتاج مساعدة فيه عشان اساعدك بشكل أفضل 🙏','["اجابه","البوصله","ايه،","الدرس","الاول","الدراسات","الاجتماعيه","بيكون","دروس","مهم","جداً،","وبيتناول","موضوعات","اساسيه","المجتمع","والثقافه","والبيءه،","وبيشرح","الاستاذ","يوسف","بركات","كيف","ونحلل","العلاقات","الافراد","والمجتمعات،","وبيتكلم","اهميه","حياتنا","اليوميه،","وبيعرفك","علي","كيفيه","استخدام","المفاهيم","والاساليب","لتحليل","القضايا","المختلفه،","وبيخليك","تعرف","تطور","مهاراتك","التفكير","النقدي","والتحليل،","ولو","محتاج","شرح","توضيح","نقطه","الدرس،","هنا","عشان","اساعدك،","اتمني","جزء","مساعده","فيه","اساعدك","بشكل","افضل"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785950013140);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('LefWEXcZtbGwNWmWst5t','بس لو عايز تعرف أكتر عن المنصة أو تسجل فيها، أتأكد إنك تقدر تتواصل مع الأستاذ يوسف بركات على رقم [01023675235](tel:01023675235) أو تروح لقناة اليوتيوب بتاعته [قناة الأستاذ يوسف بركات](https://www.youtube.com/@youssefbarakat) أو صفحته على الفيسبوك [صفحة الأستاذ يوسف بركات](https://www.facebook.com/youssefbarakatofficial/) أو تتواصل معاه على الواتساب [الواتساب](https://wa.me/201023675235)','["عايز","تعرف","اكتر","المنصه","تسجل","فيها،","اتاكد","انك","تقدر","تتواصل","الاستاذ","يوسف","بركات","علي","رقم","01023675235","tel","تروح","لقناه","اليوتيوب","بتاعته","قناه","https","www","youtube","com","youssefbarakat","صفحته","الفيسبوك","صفحه","facebook","youssefbarakatofficial","معاه","الواتساب","201023675235"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785781772431);
