INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('LrZipmGW2HZmgx85a0Iu','سؤال الطالب: الي ف الاسبوع الي بعده إجابة البوصلة: الامتحان يوم الأربعاء الساعة 9 مساءً ومواعيد المنصة الثابتة هي: - للمرحلة الإعدادية: شرح وتدريب يوم الخميس، واجب يوم الثلاثاء، امتحان يوم الأربعاء الساعة 9 مساءً - للمرحلة الثانوية: شرح وتدريب يوم الجمعة، واجب يوم الثلاثاء، امتحان يوم الأربعاء الساعة 9 مساءً.','["سءال","الطالب","الي","الاسبوع","بعده","اجابه","البوصله","الامتحان","يوم","الاربعاء","الساعه","مساءً","ومواعيد","المنصه","الثابته","للمرحله","الاعداديه","شرح","وتدريب","الخميس،","واجب","الثلاثاء،","امتحان","الثانويه","الجمعه،"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785952578916);
