INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('NYoRIo8IyrJoJ5QxEruA','سؤال الطالب: بطل وجميل لا ده انت سكر خالص، هبرمجك دلوقتي تظبط عشان شكلك عاوز تعملنا مشكلة إجابة البوصلة: يا جنى يا جميل، أنا آسف إذا كنت قد أزعجتك بأي شكل من الأشكال أنا هنا لمساعدتك فقط، ولا أريد أن أسبب أي مشكلة أنا برنامج مصمم لتقديم المساعدة والتعليم، وليس لدي نية لخلق مشاكل','["سءال","الطالب","بطل","وجميل","سكر","خالص،","هبرمجك","دلوقتي","تظبط","عشان","شكلك","عاوز","تعملنا","مشكله","اجابه","البوصله","جني","جميل،","اسف","كنت","ازعجتك","باي","شكل","الاشكال","هنا","لمساعدتك","فقط،","ولا","اريد","اسبب","برنامج","مصمم","لتقديم","المساعده","والتعليم،","وليس","لدي","نيه","لخلق","مشاكل"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785359745750);
