INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('NiJvDhgcKLzIIGP38Nz0','سؤال الطالب: السلام عليكم ورحمه الله وبركاته هل المستر نزل محاضرات إجابة البوصلة: يا أيه، المستر يوسف بركات دايماً بينزل محاضرات جديدة، ممكن تفتح الكورس وتشوف اخر ما نزل، أو تتابعنا على [قناة اليوتيوب](https://www.youtube.com/@youssefbarakat) أو [صفحة الفيسبوك](https://www.facebook.com/youssefbarakatofficial/) علشان تاخد كل التحديثات الجديدة.','["سءال","الطالب","السلام","عليكم","ورحمه","الله","وبركاته","المستر","نزل","محاضرات","اجابه","البوصله","ايه،","يوسف","بركات","دايماً","بينزل","جديده،","ممكن","تفتح","الكورس","وتشوف","اخر","نزل،","تتابعنا","علي","قناه","اليوتيوب","https","www","youtube","com","youssefbarakat","صفحه","الفيسبوك","facebook","youssefbarakatofficial","علشان","تاخد","التحديثات","الجديده"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785521510688);
