INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('OkxQPS2vlPFRC1a0P60y','سؤال الطالب: اعمل لي اختبار على الدرس ااول إجابة البوصلة: يا رؤى، هعمل لك اختبار قصير على الدرس الأول أتمنى أن تنجح بتفوق سؤال 1: إيه هي القارة الأكبر في العالم ج) أمريكا الشمالية سؤال 2: إيه هي القارة اللي بتتسمى القارة البيضاء أ) أنتاركتيكا سؤال 3: إيه هي القارة اللي فيها استراليا د) أوقيانوسيا أجيب على الأسئلة دي وأنا هقلك إزاي جاوبت!','["سءال","الطالب","اعمل","اختبار","علي","الدرس","ااول","اجابه","البوصله","رءي،","هعمل","قصير","الاول","اتمني","تنجح","بتفوق","ايه","القاره","الاكبر","العالم","امريكا","الشماليه","اللي","بتتسمي","البيضاء","انتاركتيكا","فيها","استراليا","اوقيانوسيا","اجيب","الاسءله","وانا","هقلك","ازاي","جاوبت"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785754664292);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('PHl9QaArEJGcPR5NsZ08','سؤال الطالب: لا هو بيتقال كده ازاي اعمل ريفيس إجابة البوصلة: يا جنى، تقدر تعمل ريفرش للصفحة بسهولة عن طريق الضغط على زر الف5 على لوحة المفاتيح أو من خلال قائمة المتصفح.','["سءال","الطالب","بيتقال","كده","ازاي","اعمل","ريفيس","اجابه","البوصله","جني،","تقدر","تعمل","ريفرش","للصفحه","بسهوله","طريق","الضغط","علي","الف5","لوحه","المفاتيح","قاءمه","المتصفح"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786623260659);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('PIOeCgu7kKUNlYsYBxy6','وأنا هنا إذا كان عندك أي سؤال أو محتاج مساعدة في فهم أي نقطة.','["وانا","هنا","عندك","سءال","محتاج","مساعده","فهم","نقطه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785395140461);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('PLfL0Mk48Yk8gWSfHDC4','إجابة البوصلة: يا أيه، أنا فهمت، أنت بتقول إن المحاضرات بتتحدد وقتها وبتتخلص بعد كدا، ولا تقعد موجودة طول الترم، ده عشان المنصة بتتبع نظام محدد لشرح وتدريب وامتحان، وده بيعني إن كل محاضرة بتكون لها وقتها المحدد، وبعد ما المحاضرة تخلص، بتتخلص المحاضرة دي وبتتجدد المحاضرات الجديدة، وده بيساعد الطلاب على التركيز على المحاضرات اللي جاية وعدم التأخر في المادة الدراسية.','["اجابه","البوصله","ايه،","فهمت،","بتقول","المحاضرات","بتتحدد","وقتها","وبتتخلص","كدا،","ولا","تقعد","موجوده","طول","الترم،","عشان","المنصه","بتتبع","نظام","محدد","لشرح","وتدريب","وامتحان،","وده","بيعني","محاضره","بتكون","لها","المحدد،","وبعد","المحاضره","تخلص،","بتتخلص","وبتتجدد","الجديده،","بيساعد","الطلاب","علي","التركيز","اللي","جايه","وعدم","التاخر","الماده","الدراسيه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786554328664);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('Py681CcUuo8AJXHWV8da','سؤال الطالب: انا مكنتش اعرف انو دخلت قبل كدا إجابة البوصلة: يا ريهام، لا مشكلة، ممكن تكون دخلت قبل كدا ولم تلاحظي، لو عايزة تعرفي تفاصيل عن الكورسات اللي دخلت عليها، ممكن أقدر أساعدك؟','["سءال","الطالب","مكنتش","اعرف","انو","دخلت","كدا","اجابه","البوصله","ريهام،","مشكله،","ممكن","تكون","ولم","تلاحظي،","عايزه","تعرفي","تفاصيل","الكورسات","اللي","عليها،","اقدر","اساعدك؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786812262948);
