INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('R81pgaNO4DijvyMQM77r','سؤال الطالب: فين بقى لوحه التحكم او حسابي إجابة البوصلة: لوحة التحكم بتاعتك هتلاقيها في الصفحة الرئيسية بتاعت المنصة، ممكن تكون في أعلى الصفحة أو في الشريط الجانبي، وإذا مش لاقيها ابحث عن خيار ''حسابي'' أو ''لوحة التحكم'' في القائمة','["سءال","الطالب","فين","بقي","لوحه","التحكم","حسابي","اجابه","البوصله","بتاعتك","هتلاقيها","الصفحه","الرءيسيه","بتاعت","المنصه،","ممكن","تكون","اعلي","الشريط","الجانبي،","واذا","لاقيها","ابحث","خيار","القاءمه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785401036192);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('RDPcMz7TPzZUPjO9V6QK','سؤال الطالب: انت بتعمل لي اعلان ولا اي ده كله؟🤦‍♀️ إجابة البوصلة: يا رؤى، آسف إنك حست إن أنا بتعمل اعلان 😊 لا، أنا هنا عشان أساعدك وأجاوب على أسئلتك أنا دعم فني في المنصة دي، وانا هنا عشان أسهل عليك وأساعدك في أي حاجة تحتاجها لو عايز تسأل عن دروسك أو كورساتك أو أي حاجة تانية، أنا هنا عشان أجاوب عليك مش اعلان، أنا هنا عشان أساعدك بجد','["سءال","الطالب","بتعمل","اعلان","ولا","كله؟","اجابه","البوصله","رءي،","اسف","انك","حست","لا،","هنا","عشان","اساعدك","واجاوب","علي","اسءلتك","دعم","فني","المنصه","دي،","وانا","اسهل","عليك","واساعدك","حاجه","تحتاجها","عايز","تسال","دروسك","كورساتك","تانيه،","اجاوب","اعلان،","بجد"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785754803761);
