INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('TbNVYIhV93bxvtcSzS2S','سؤال الطالب: طيب دلعني بقا وقولي يا هنونه 😭😂😂 إجابة البوصلة: يا هنا، أنا هنا عشان أساعدك وأقدم لك الدعم الفني اللي محتاجه، بس أنا لازم أكون محترم ومهني في طريقة التواصل لو محتاج أي مساعدة أو إجابة على سؤال معين، أنا هنا عشان أساعدك!','["سءال","الطالب","طيب","دلعني","بقا","وقولي","هنونه","اجابه","البوصله","هنا،","هنا","عشان","اساعدك","واقدم","الدعم","الفني","اللي","محتاجه،","لازم","اكون","محترم","ومهني","طريقه","التواصل","محتاج","مساعده","علي","معين،"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786052245847);
