INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('Um8BdT0l81yhANv6KoNA','سؤال الطالب: تااعدادي إجابة البوصلة: طيب، دراسات اجتماعية للمرحلة الإعدادية أنا هنا لأساعدك في أي شيء محتاجه، سواء كان سؤال أو شرح لموضوع معين مثلاً، ممكن تسألني عن تاريخ أو جغرافيا أو اجتماعيات أو حتى مدني أو محتاج تعلم كيف تحل أسئلة معينة أو حتى محتاج نصايح للاستعداد للامتحانات قوللي، إزاي أقدر أساعدك؟','["سءال","الطالب","تااعدادي","اجابه","البوصله","طيب،","دراسات","اجتماعيه","للمرحله","الاعداديه","هنا","لاساعدك","شيء","محتاجه،","سواء","شرح","لموضوع","معين","مثلاً،","ممكن","تسالني","تاريخ","جغرافيا","اجتماعيات","حتي","مدني","محتاج","تعلم","كيف","تحل","اسءله","معينه","نصايح","للاستعداد","للامتحانات","قوللي،","ازاي","اقدر","اساعدك؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785784733124);
