INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('VdkA62MX6bC2r9kAcGlC','إجابة البوصلة: يا أيه، آسف جداً أنك واجهت مشكلة في دخول الامتحان، أنا هنا لمساعدتك، يمكنك أن تتواصل مباشرة مع الدعم الفني على الرقم 01023675235، وهم سوف يساعدونك في حل المشكلة، أو يمكنني أن أبلغ عن المشكلة لهم من طرفك، فقط 告لي ما هي المشكلة بالضبط التي تواجهها في دخول الامتحان؟','["اجابه","البوصله","ايه،","اسف","جداً","انك","واجهت","مشكله","دخول","الامتحان،","هنا","لمساعدتك،","يمكنك","تتواصل","مباشره","الدعم","الفني","علي","الرقم","01023675235،","وهم","سوف","يساعدونك","المشكله،","يمكنني","ابلغ","المشكله","لهم","طرفك،","فقط","بالضبط","تواجهها","الامتحان؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785962764452);
