INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('WAS3jLA6WDzhMkgbxIhL','سؤال الطالب: تاريخ وجغرافيا إجابة البوصلة: طيب، تاريخ وجغرافيا للمرحلة الإعدادية في تاريخ، ممكن نغطي مواضيع مثل: * تاريخ مصر القديمة * تاريخ الإسلام * تاريخ العالم القديم * تاريخ مصر الحديثة وفي جغرافيا، ممكن نغطي مواضيع مثل: * جغرافيا مصر * جغرافيا العالم * دراسة المناخ والتربة * دراسة المدن والقرى أي من هذه المواضيع محتاج شرح أو مساعدة','["سءال","الطالب","تاريخ","وجغرافيا","اجابه","البوصله","طيب،","للمرحله","الاعداديه","تاريخ،","ممكن","نغطي","مواضيع","مصر","القديمه","الاسلام","العالم","القديم","الحديثه","وفي","جغرافيا،","جغرافيا","دراسه","المناخ","والتربه","المدن","والقري","المواضيع","محتاج","شرح","مساعده"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785784765774);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('Wtp1EWPz0ux8HlGC3Ksr','إجابة البوصلة: يا أيه، السلام عليكم ورحمة الله وبركاته، بالنسبة لمواعيد الامتحانات، المنصة بتحدد مواعيد ثابتة، يعني الامتحانات بتبقى الساعة 9 مساءً يوم الأربعاء للمرحلة الإعدادية والثانوية، وممكن تلاقي شرح وتدريب يوم الخميس للمرحلة الإعدادية، والجمعة للمرحلة الثانوية، وواجب يوم الثلاثاء، ده المواعيد اللي المنصة بتتبعها، لو محتاج أي مساعدة أو شرح في أي حاجة قبل الامتحان، أنا هنا عشان اساعدك 🙏','["اجابه","البوصله","ايه،","السلام","عليكم","ورحمه","الله","وبركاته،","بالنسبه","لمواعيد","الامتحانات،","المنصه","بتحدد","مواعيد","ثابته،","يعني","الامتحانات","بتبقي","الساعه","مساءً","يوم","الاربعاء","للمرحله","الاعداديه","والثانويه،","وممكن","تلاقي","شرح","وتدريب","الخميس","الاعداديه،","والجمعه","الثانويه،","وواجب","الثلاثاء،","المواعيد","اللي","بتتبعها،","محتاج","مساعده","حاجه","الامتحان،","هنا","عشان","اساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785949834255);
