INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('Y0fjB53IyRDRyqrLeYLi','سؤال الطالب: انا سجلت وكنت واخده ترم كامل مجانا ولسه متفرجرتش علي اول درس دراسات تالته اعدادي إجابة البوصلة: طيب هتفرج على الدرس الأول دلوقتي أنا هساعدك لو واجهت أي مشكلة أو لو محتج لشرح أي حاجة ومتنساش إن المنصة دي بتديك فرصة للاستفادة من الترم كامل مجانًا، فاستغلها ولو محتج أي مساعدة أنا موجود','["سءال","الطالب","سجلت","وكنت","واخده","ترم","كامل","مجانا","ولسه","متفرجرتش","علي","اول","درس","دراسات","تالته","اعدادي","اجابه","البوصله","طيب","هتفرج","الدرس","الاول","دلوقتي","هساعدك","واجهت","مشكله","محتج","لشرح","حاجه","ومتنساش","المنصه","بتديك","فرصه","للاستفاده","الترم","مجانًا،","فاستغلها","ولو","مساعده","موجود"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785606942545);
