INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('ZRcLWjGn3DQKEej7HBmw','سؤال الطالب: لو سمحت هل جهز الواجب ولا لسه إجابة البوصلة: يا أيه، الواجب بيتم نشره يوم الثلاثاء، فلو مش لسه ظهر معاك دلوقتي ممكن يكون لسه في عمليه النشر، جرب تrefresh الصفحه او تروح للصفحه الرئيسيه وتجيبها تاني، لو لسه مش ظهر معاك هتاخد مني حل تاني ان شاء الله 🙏','["سءال","الطالب","سمحت","جهز","الواجب","ولا","لسه","اجابه","البوصله","ايه،","بيتم","نشره","يوم","الثلاثاء،","فلو","ظهر","معاك","دلوقتي","ممكن","يكون","عمليه","النشر،","جرب","تrefresh","الصفحه","تروح","للصفحه","الرءيسيه","وتجيبها","تاني،","هتاخد","مني","تاني","شاء","الله"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785870823403);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('ZX7RHNeYsjabo3OyWQzs','أو ممكن تختار جملة قصيرة و تاخد الحرف الأول من كل كلمة، مثل: "أنا أحب التعلم" و تاخد "أ ح ت" أيًا كان، تأكد إنك تختار كلمة مرور قوية و آمنة و مش سهلة النسيان.','["ممكن","تختار","جمله","قصيره","تاخد","الحرف","الاول","كلمه،","احب","التعلم","ايًا","كان،","تاكد","انك","كلمه","مرور","قويه","امنه","سهله","النسيان"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785409930516);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('ZYMjews36OveFLqttCcU','إجابة البوصلة: مواعيد الكورسات هتكون متاحة قريباً على منصاتنا، اتفضل تابعنا على [قناة اليوتيوب](https://www.youtube.com/@youssefbarakat) أو [صفحة الفيسبوك](https://www.facebook.com/youssefbarakatofficial/) أو [الواتساب](https://wa.me/201023675235) عشان تاخد كل التحديثات اللي هتحتاجها عن مواعيد الكورسات لأولي ثانوي وأي استفسار تاني أنا هنا لأساعدك!','["اجابه","البوصله","مواعيد","الكورسات","هتكون","متاحه","قريباً","علي","منصاتنا،","اتفضل","تابعنا","قناه","اليوتيوب","https","www","youtube","com","youssefbarakat","صفحه","الفيسبوك","facebook","youssefbarakatofficial","الواتساب","201023675235","عشان","تاخد","التحديثات","اللي","هتحتاجها","لاولي","ثانوي","واي","استفسار","تاني","هنا","لاساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785798474985);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('ZoLNAoSkZYU3pet5IueY','سؤال الطالب: احنا هناخد الحصه الجايه امتي إجابة البوصلة: يا محمود، مواعيد الحصص بتختلف حسب المرحلة اللي أنتا فيها أنتا لسه ما دخلتش في أي كورس، فلو بتبحث عن مواعيد الحصص، تقدر تختار المرحلة اللي أنتا فيها، وإذا كنت إعدادية، الحصة بتكون يوم الخميس، وإذا كنت ثانوية، الحصة بتكون يوم الجمعة.','["سءال","الطالب","احنا","هناخد","الحصه","الجايه","امتي","اجابه","البوصله","محمود،","مواعيد","الحصص","بتختلف","حسب","المرحله","اللي","انتا","فيها","لسه","دخلتش","كورس،","فلو","بتبحث","الحصص،","تقدر","تختار","فيها،","واذا","كنت","اعداديه،","بتكون","يوم","الخميس،","ثانويه،","الجمعه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786617914236);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('ZovqsBOfPNj14K6gUBDS','بعد كدا جاء الأوروبيين وبدأوا بالاستعمار، وده أدى لتغيير كبير في الثقافة والاقتصاد والسياسة في هذه المناطق هل عندك سؤال معين عن تاريخ العالم الجديد؟','["كدا","جاء","الاوروبيين","وبداوا","بالاستعمار،","وده","ادي","لتغيير","كبير","الثقافه","والاقتصاد","والسياسه","المناطق","عندك","سءال","معين","تاريخ","العالم","الجديد؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785781782402);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('a3dAr0nqHRroC3V6h4bq','سؤال الطالب: بص بيعملي الواجب مكتمل قبل ما انا احله حتي إجابة البوصلة: يا يوسف، ده مش عادي ممكن يكون هناك خطأ تقني في النظام أو في تسجيل الإجابات أتمنى أنك تتواصل مع الدعم الفني على رقم ٠١٠٢٣٦٧٥٢٣٥ عشان يفحصوا القضية ويحلوها لك.','["سءال","الطالب","بيعملي","الواجب","مكتمل","احله","حتي","اجابه","البوصله","يوسف،","عادي","ممكن","يكون","هناك","خطا","تقني","النظام","تسجيل","الاجابات","اتمني","انك","تتواصل","الدعم","الفني","علي","رقم","٠١٠٢٣٦٧٥٢٣٥","عشان","يفحصوا","القضيه","ويحلوها"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786477408506);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('aU0kugu7QPSAdexGISVi','سؤال الطالب: ممكن أسأل سوال في ماده الدراسات إجابة البوصلة: يا أيه، أسأل بلا تردد أنا هنا عشان أساعدك في ماده الدراسات إنتظر بس سؤالك عشان أجاوبك عليه.','["سءال","الطالب","ممكن","اسال","سوال","ماده","الدراسات","اجابه","البوصله","ايه،","بلا","تردد","هنا","عشان","اساعدك","انتظر","سءالك","اجاوبك","عليه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785443031718);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('aZ7gntuFnFr9EFn2h6ly','مثلًا، إذا كنت تريد التواصل مع الأستاذ يوسف بركات، ممكن تراسله على بريده الإلكتروني، و هو مثلًا: [youssefbarakat@example.com](mailto:youssefbarakat@example.com) أو ممكن تتواصل معه عن طريق منصات التواصل الاجتماعي، مثل: [قناة اليوتيوب](https://www.youtube.com/@youssefbarakat) [صفحة الفيسبوك](https://www.facebook.com/youssefbarakatofficial/)','["مثلًا،","كنت","تريد","التواصل","الاستاذ","يوسف","بركات،","ممكن","تراسله","علي","بريده","الالكتروني،","مثلًا","youssefbarakat","example","com","mailto","تتواصل","معه","طريق","منصات","الاجتماعي،","قناه","اليوتيوب","https","www","youtube","صفحه","الفيسبوك","facebook","youssefbarakatofficial"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785410092249);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('amZdVTiJFVTbMVkBPtms','سؤال الطالب: ماشي إجابة البوصلة: يا لمياء، مينفعش نستمر كده ممكن تساعديني أكتر فيه حاجة معينة مش عارفة تعمليها في المنصة أو عندك سؤال في الدرس أنا هساعدك بأي حاجة محتاجةها.','["سءال","الطالب","ماشي","اجابه","البوصله","لمياء،","مينفعش","نستمر","كده","ممكن","تساعديني","اكتر","فيه","حاجه","معينه","عارفه","تعمليها","المنصه","عندك","الدرس","هساعدك","باي","محتاجهها"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785396108844);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('as5vsXv0Y2AUXkjb31wp','إذا كنت لا تزال تواجه صعوبة في العثور على الفيديو، يمكنك التواصل مع الأستاذ يوسف بركات مباشرة عبر رقم الهاتف 01023675235 أو عبر الواتساب [الواتساب](https://wa.me/201023675235) لطلب المساعدة.','["كنت","تزال","تواجه","صعوبه","العثور","علي","الفيديو،","يمكنك","التواصل","الاستاذ","يوسف","بركات","مباشره","رقم","الهاتف","01023675235","الواتساب","https","201023675235","لطلب","المساعده"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785859564565);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('auUqI8x5BE3R58WhdU7J','سؤال الطالب: مش فاهمه المحضرة التعريفيه إجابة البوصلة: يا ايتن، المحاضرة التعريفية بتبقى أول محاضرة في الكورس، وهي بتقدم معلومات عامة عن المادة الدراسية وبيان أهداف الكورس ممكن أساعدك أفهم نقطة معينة فيها أو نبدأ من الأول ونشرحها سوا؟','["سءال","الطالب","فاهمه","المحضره","التعريفيه","اجابه","البوصله","ايتن،","المحاضره","بتبقي","اول","محاضره","الكورس،","وهي","بتقدم","معلومات","عامه","الماده","الدراسيه","وبيان","اهداف","الكورس","ممكن","اساعدك","افهم","نقطه","معينه","فيها","نبدا","الاول","ونشرحها","سوا؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785781660559);
