INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('bJroWWn6byEjPV1zak59','سؤال الطالب: أنا عملت كده في امتحان المنصه وطلع ده السوال االوحيد اللي غلط وجبت ٩٢ إجابة البوصلة: يا أيه، مبروك على النتيجة الحلوة 92 هي نتيجة ممتازة، و أنك أخطأت في سؤال واحد فقط يعني أنك مستوىك كويس جداً متابعة دراستك و استمر في التعلم و التمارين و هتلاقي نفسك بتتقدم أكتر و أكتر لو عندك أي أسئلة أو محتاج مساعدة في أي حاجة، أنا هنا لأساعدك.','["سءال","الطالب","عملت","كده","امتحان","المنصه","وطلع","السوال","االوحيد","اللي","غلط","وجبت","اجابه","البوصله","ايه،","مبروك","علي","النتيجه","الحلوه","نتيجه","ممتازه،","انك","اخطات","واحد","فقط","يعني","مستويك","كويس","جداً","متابعه","دراستك","استمر","التعلم","التمارين","هتلاقي","نفسك","بتتقدم","اكتر","عندك","اسءله","محتاج","مساعده","حاجه،","هنا","لاساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785443289767);
