INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('bokzJmEtChSccs5KLve9','سؤال الطالب: هو انا مسجله حساب إجابة البوصلة: مرحباً بك في منصة الأستاذ يوسف بركات أنا سعيد أنك مسجل حساب هنا كيف يمكنني مساعدتك اليوم هل لديك أسئلة أو تحتاج إلى شرح أو تدريب في الدراسات الاجتماعية؟','["سءال","الطالب","مسجله","حساب","اجابه","البوصله","مرحباً","منصه","الاستاذ","يوسف","بركات","سعيد","انك","مسجل","هنا","كيف","يمكنني","مساعدتك","اليوم","لديك","اسءله","تحتاج","الي","شرح","تدريب","الدراسات","الاجتماعيه؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785860216429);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('bwVhcuG6FYHmE9ccyZIH','سؤال الطالب: مش ظهر إجابة البوصلة: يا أيه، ممكن يكون فيه مشكلة في النشر أو في المنصة، هتاخد منك المفتاح السري عشان أفتح الكورس وأشوف ايه اللي حصل، لو سمحت قول لي المفتاح السري بتاعك عشان أستطع مساعدتك بأسرع ما يمكن 🙏','["سءال","الطالب","ظهر","اجابه","البوصله","ايه،","ممكن","يكون","فيه","مشكله","النشر","المنصه،","هتاخد","منك","المفتاح","السري","عشان","افتح","الكورس","واشوف","ايه","اللي","حصل،","سمحت","قول","بتاعك","استطع","مساعدتك","باسرع","يمكن"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785870853147);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('c255dOEARPi3iDuZqqLe','هما هيساعدوك في عملية الاشتراك وبيساعدوك في أي سؤال أو استفسار عندك.','["هما","هيساعدوك","عمليه","الاشتراك","وبيساعدوك","سءال","استفسار","عندك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785232972860);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('cOMscOxB42VHkbViUPbE','سؤال الطالب: انا يوسف بركات يبني وبقولك قول لي كام طالب فى المنصة عندي إجابة البوصلة: أهلاً بيك يا أستاذ يوسف بركات أنا سعيد أن أسمع منك حسناً، عدد الطلاب المسجلين بالمنصة هو 12 طالب أتمنى أن تزداد الأعداد قريباً هل هناك شيء آخر يمكنني مساعدتك به؟','["سءال","الطالب","يوسف","بركات","يبني","وبقولك","قول","كام","طالب","المنصه","عندي","اجابه","البوصله","اهلاً","بيك","استاذ","سعيد","اسمع","منك","حسناً،","عدد","الطلاب","المسجلين","بالمنصه","اتمني","تزداد","الاعداد","قريباً","هناك","شيء","اخر","يمكنني","مساعدتك","به؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785202771433);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('ceI5KfDongeGEfeVkg7Q','سؤال الطالب: دى منصه اولى اعدادى إجابة البوصلة: أهلاً بيكى فى منصة الأستاذ يوسف بركات أنا هنا عشان أساعدك فى دراستك و أجاوب على أسئلتك فى تالتة اعدادى، مواعيد المنصة هى: شرح وتدريب يوم الخميس، واجب يوم الثلاثاء، وامتحان يوم الأربعاء الساعة 9 مساءً إزاى أستطيع مساعدتك اليوم؟','["سءال","الطالب","منصه","اولي","اعدادي","اجابه","البوصله","اهلاً","بيكي","الاستاذ","يوسف","بركات","هنا","عشان","اساعدك","دراستك","اجاوب","علي","اسءلتك","تالته","اعدادي،","مواعيد","المنصه","شرح","وتدريب","يوم","الخميس،","واجب","الثلاثاء،","وامتحان","الاربعاء","الساعه","مساءً","ازاي","استطيع","مساعدتك","اليوم؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786465457280);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('d9DhrEhsVQAiyKUBgs9Q','سؤال الطالب: انا عملت حساب جديد تكيت على كلمه حساب جديد وكل البيانات إجابة البوصلة: حسناً لو كنت عملت حساب جديد وكتبت كل البيانات، وأنت عايز ترجع لصفحة الإيميل بتاعتك، ممكن تجرب الخطوات دي: تروح لصفحة الإيميل بتاعتك وكتib إسم المستخدم وكلمة المرور اللي كتبتها لما عملت الحساب','["سءال","الطالب","عملت","حساب","جديد","تكيت","علي","كلمه","وكل","البيانات","اجابه","البوصله","حسناً","كنت","وكتبت","البيانات،","وانت","عايز","ترجع","لصفحه","الايميل","بتاعتك،","ممكن","تجرب","الخطوات","تروح","بتاعتك","وكتib","اسم","المستخدم","وكلمه","المرور","اللي","كتبتها","لما","الحساب"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785588899448);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('dIg7Lxm2OvKa4ARYogIq','سؤال الطالب: الكورس الاول مجاني وبردو بيقولي ادفع إجابة البوصلة: يا مالك، ممكن تكون هناك مشكلة في النظام، أو أنك محتاج تسجل دخول تاني جرب تسجل خروج وتسجل دخول تاني، أو اطلب مني المفتاح السري عشان أستطيع مساعدتك بشكل أفضل.','["سءال","الطالب","الكورس","الاول","مجاني","وبردو","بيقولي","ادفع","اجابه","البوصله","مالك،","ممكن","تكون","هناك","مشكله","النظام،","انك","محتاج","تسجل","دخول","تاني","جرب","خروج","وتسجل","تاني،","اطلب","مني","المفتاح","السري","عشان","استطيع","مساعدتك","بشكل","افضل"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785412162221);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('dTvOyeYo0ZSzp4vSs3Tr','سؤال الطالب: مش عارف إجابة البوصلة: لا تقلق، أنا هنا عشان أساعدك لو محتاج مساعدة في فهم حاجة معينة أو عايز تتابع دروس معينة، قول لي وأنا هساعدك','["سءال","الطالب","عارف","اجابه","البوصله","تقلق،","هنا","عشان","اساعدك","محتاج","مساعده","فهم","حاجه","معينه","عايز","تتابع","دروس","معينه،","قول","وانا","هساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785696765931);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('dZ37eur3uzpMDQsa0TI9','سؤال الطالب: و باقي القارات كلتهم يعني؟ إجابة البوصلة: يا رؤى، ترتيب القارات كالتالي: أفريقيا، أنتاركتيكا، آسيا، أوروبا، وأمريكا الشمالية وأمريكا الجنوبية بس لو عايز ترتيب حسب المساحة، فهي كالتالي: آسيا، أفريقيا، أمريكا الشمالية، أمريكا الجنوبية، أنتاركتيكا، أوروبا، وأوقيانوسيا.','["سءال","الطالب","باقي","القارات","كلتهم","يعني؟","اجابه","البوصله","رءي،","ترتيب","كالتالي","افريقيا،","انتاركتيكا،","اسيا،","اوروبا،","وامريكا","الشماليه","الجنوبيه","عايز","حسب","المساحه،","فهي","امريكا","الشماليه،","الجنوبيه،","واوقيانوسيا"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785754598232);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('dw2QHJqkKsNXfdwZzDrm','سؤال الطالب: طيب أنا المستر هل مصدقني إجابة البوصلة: يا بطل أنا لا أستطيع أن أقول إنني مصدقك أو لا، لأنني لا أعرف ما تقول إذا كنت تريد أن تتحدث عن شيء معين، أرجو أن تشرح أكثر حتى أستطيع فهمك بشكل أفضل لكن إذا كنت تريد أن تتحدث مع المستر يوسف بركات، يمكنك الاتصال به مباشرة على الرقم 01023675235 هو سوف يستمع لك وسيجيب على أسئلتك','["سءال","الطالب","طيب","المستر","مصدقني","اجابه","البوصله","بطل","استطيع","اقول","انني","مصدقك","لا،","لانني","اعرف","تقول","كنت","تريد","تتحدث","شيء","معين،","ارجو","تشرح","حتي","فهمك","بشكل","افضل","يوسف","بركات،","يمكنك","الاتصال","مباشره","علي","الرقم","01023675235","سوف","يستمع","وسيجيب","اسءلتك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785202748643);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('dy8YtRpxLAZhuWPILDLs','إذا كنت عايز تشترك في منصة الأستاذ يوسف بركات، ممكن تتواصل مع الإدارة على الرقم 01023675235، أو تتواصل معنا من خلال [قناة اليوتيوب](https://www.youtube.com/@youssefbarakat) أو [صفحة الفيسبوك](https://www.facebook.com/youssefbarakatofficial/) أو [الواتساب](https://wa.me/201023675235)','["كنت","عايز","تشترك","منصه","الاستاذ","يوسف","بركات،","ممكن","تتواصل","الاداره","علي","الرقم","01023675235،","معنا","قناه","اليوتيوب","https","www","youtube","com","youssefbarakat","صفحه","الفيسبوك","facebook","youssefbarakatofficial","الواتساب","201023675235"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785232972262);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('e7JR51EvAUpB9Mcy75fw','أو إذا كنت تريد أن تتواصل معه عبر وسائل التواصل الاجتماعي، يمكنك زيارة صفحته على الفيسبوك [صفحة الأستاذ يوسف بركات](https://www.facebook.com/youssefbarakatofficial/) أو قناة اليوتيوب الخاصة به [قناة الأستاذ يوسف بركات](https://www.youtube.com/@youssefbarakat) سوف تجد كل المعلومات التي تحتاجها هناك.','["كنت","تريد","تتواصل","معه","وساءل","التواصل","الاجتماعي،","يمكنك","زياره","صفحته","علي","الفيسبوك","صفحه","الاستاذ","يوسف","بركات","https","www","facebook","com","youssefbarakatofficial","قناه","اليوتيوب","الخاصه","youtube","youssefbarakat","سوف","تجد","المعلومات","تحتاجها","هناك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785202748788);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('eH5p9AwqOnq7Tf8b3kbC','سؤال الطالب: عاوز اقدم شكوى إجابة البوصلة: تمام، أنا هنا لاستقبال شكويتك يمكنكsharing معي ما هي المشكلة التي واجهتها هل هي متعلقة بالمنصة أو بالدروس أو بأي شيء آخر سأحاول مساعدتك في حل المشكلة أو إرسالها إلى الإدارة إذا لزم الأمر وإذا كنت تريد التحدث مباشرة مع الإدارة، يمكنك الاتصال على الرقم 01023675235','["سءال","الطالب","عاوز","اقدم","شكوي","اجابه","البوصله","تمام،","هنا","لاستقبال","شكويتك","يمكنكsharing","معي","المشكله","واجهتها","متعلقه","بالمنصه","بالدروس","باي","شيء","اخر","ساحاول","مساعدتك","ارسالها","الي","الاداره","لزم","الامر","واذا","كنت","تريد","التحدث","مباشره","الاداره،","يمكنك","الاتصال","علي","الرقم","01023675235"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785181445213);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('eaNcxumSmFmpONtkKX4n','سؤال الطالب: فين الإمتحان الي المستر قال عليه إجابة البوصلة: يا هنا، الإمتحانات بتتقام يوم الأربعاء الساعة 9 مساءً إذا كنت من المرحلة الإعدادية، فالإمتحان هيبقى يوم الأربعاء الساعة 9 مساءً بعد ما تكون درست وتدربت يوم الخميس السابق وإذا كنت من المرحلة الثانوية، فالإمتحان هيبقى يوم الأربعاء الساعة 9 مساءً بعد ما تكون درست وتدربت يوم الجمعة السابق','["سءال","الطالب","فين","الامتحان","الي","المستر","قال","عليه","اجابه","البوصله","هنا،","الامتحانات","بتتقام","يوم","الاربعاء","الساعه","مساءً","كنت","المرحله","الاعداديه،","فالامتحان","هيبقي","تكون","درست","وتدربت","الخميس","السابق","واذا","الثانويه،","الجمعه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786052158042);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('emuoamNBFAzDbA9le1vo','أو ممكن تتواصل مع الأستاذ يوسف بركات مباشرة على [الصفحة الرسمية على الفيسبوك](https://www.facebook.com/youssefbarakatofficial/) أو على [الواتساب](https://wa.me/201023675235) عشان تسأله عن أى شئ متعلق بالفيديوهات أو الدراسة وأخيراً، لو محتاج مساعدة أو إرشاد في شئ معين، أنا هنا عشان أساعدك!','["ممكن","تتواصل","الاستاذ","يوسف","بركات","مباشره","علي","الصفحه","الرسميه","الفيسبوك","https","www","facebook","com","youssefbarakatofficial","الواتساب","201023675235","عشان","تساله","متعلق","بالفيديوهات","الدراسه","واخيراً،","محتاج","مساعده","ارشاد","معين،","هنا","اساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785607301302);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('fPBPAEEZvHyYoa5Qr8Pd','سؤال الطالب: اخيرا إجابة البوصلة: يا رؤى، سعيد أنك وجدت الإجابة التي تبحث عنها إذا كنت تحتاج إلى أي مساعدة أخرى أو شرح حول أي موضوع دراسي، أنا هنا لمساعدتك لا تتردد في السؤال!','["سءال","الطالب","اخيرا","اجابه","البوصله","رءي،","سعيد","انك","وجدت","الاجابه","تبحث","عنها","كنت","تحتاج","الي","مساعده","اخري","شرح","موضوع","دراسي،","هنا","لمساعدتك","تتردد","السءال"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785440780920);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('fdX0Hj2Nq6cpYDGs4iK3','أنا هنا أساعدك في أي سؤال أو حاجة تحتاجها!','["هنا","اساعدك","سءال","حاجه","تحتاجها"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785404003891);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('fwqQLVlssViRiHf6HCXe','سؤال الطالب: حبيبي كويس المهم بقولك يعني إيه دستور إجابة البوصلة: دستور هو مجموعة القواعد والتشريعات اللي تحكم دولة ما، بتحدد حقوق وواجبات المواطنين، وتنظم السلطات الحكومية، وبتحدد شكل الحكومة وطريقة عملها يعني هو القانون الأعلى اللي بيتحكم بيها كل حاجة في الدولة.','["سءال","الطالب","حبيبي","كويس","المهم","بقولك","يعني","ايه","دستور","اجابه","البوصله","مجموعه","القواعد","والتشريعات","اللي","تحكم","دوله","ما،","بتحدد","حقوق","وواجبات","المواطنين،","وتنظم","السلطات","الحكوميه،","وبتحدد","شكل","الحكومه","وطريقه","عملها","القانون","الاعلي","بيتحكم","بيها","حاجه","الدوله"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785203425754);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('gMIBdkXYFFTO63F2cm9i','* نهر الأمازون، الذي هو واحد من أطول الأنهار في العالم أوراسيا cũng تضم العديد من المدن الكبيرة والمراكز الاقتصادية، مثل موسكو وطوكيو وباريس وبرلين وتعتبر أوراسيا مركزًا هامًا للثقافة والتاريخ والاقتصاد في العالم هل تريد أن تعرف أكثر عن تاريخ أوراسيا أو ثقافتها؟','["نهر","الامازون،","واحد","اطول","الانهار","العالم","اوراسيا","تضم","العديد","المدن","الكبيره","والمراكز","الاقتصاديه،","موسكو","وطوكيو","وباريس","وبرلين","وتعتبر","مركزًا","هامًا","للثقافه","والتاريخ","والاقتصاد","تريد","تعرف","تاريخ","ثقافتها؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785162153146);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('gNKtMZXEY60wVa3vJxKS','سؤال الطالب: أغير الإيميل إزاي إجابة البوصلة: تقدر تغير الإيميل بتاعك من خلال الضغط على ''حسابي'' أو ''الملف الشخصي''، وبعدين تلاقي خيار ''تعديل البروفايل'' أو ''تعديل الحساب''، وهناك هتلاقي خيار تغيير الإيميل.','["سءال","الطالب","اغير","الايميل","ازاي","اجابه","البوصله","تقدر","تغير","بتاعك","الضغط","علي","حسابي","الملف","الشخصي","وبعدين","تلاقي","خيار","تعديل","البروفايل","الحساب","وهناك","هتلاقي","تغيير"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785416260746);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('gSwEaFjwnNnCxYf0UMgV','سؤال الطالب: خلاص إجابة البوصلة: يا رؤى، مع السلامة، اتمنى أكون ساعدتك في حاجة، لو محتاج أي حاجة تانية، مينفعش تتردد في التواصل معانا وتذكر، منصة الأستاذ يوسف بركات دايماً معاك في دراستك، وأتمنى لك التوفيق في دراستك','["سءال","الطالب","خلاص","اجابه","البوصله","رءي،","السلامه،","اتمني","اكون","ساعدتك","حاجه،","محتاج","حاجه","تانيه،","مينفعش","تتردد","التواصل","معانا","وتذكر،","منصه","الاستاذ","يوسف","بركات","دايماً","معاك","دراستك،","واتمني","التوفيق","دراستك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785754465984);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('ge1gQS57lFUT2DlXdz2v','سؤال الطالب: لماذا يقول كلمه المرور غير صحيحة يرجى التأكد من إجابة البوصلة: حصل مشكلة لو بتقول كلمة المرور غير صحيحة، ممكن يكون هناك حاجات معينة لازم تتحقق منها: **اكتب كلمة المرور بنفسك**: متستخدمش كوبي و باست، اكتب كلمة المرور بنفسك عشان تتأكد إنها صحيحة','["سءال","الطالب","لماذا","يقول","كلمه","المرور","صحيحه","يرجي","التاكد","اجابه","البوصله","حصل","مشكله","بتقول","صحيحه،","ممكن","يكون","هناك","حاجات","معينه","لازم","تتحقق","منها","اكتب","بنفسك","متستخدمش","كوبي","باست،","عشان","تتاكد","انها"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785409872811);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('gwy2jxtzQPuD58hZCd0u','سؤال الطالب: انا دلوقتي مشتركه في المنصه ولا لا إجابة البوصلة: معلش، أنا مش عارف إنك مشترك في المنصة ولا لا، لأن أنا مجرد بوصلة مساعدة، مش عارف بياناتك الشخصية','["سءال","الطالب","دلوقتي","مشتركه","المنصه","ولا","اجابه","البوصله","معلش،","عارف","انك","مشترك","لا،","لان","مجرد","بوصله","مساعده،","بياناتك","الشخصيه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785781771904);
