INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('h8ajdmGL8jvLGKBljtI8','سؤال الطالب: مين رئيس فنزويلا الحالي إجابة البوصلة: 📊 رئيس فنزويلا الحالي هو نيكولاس مادورو هل تحتاج لمعلومات أخرى؟','["سءال","الطالب","مين","رءيس","فنزويلا","الحالي","اجابه","البوصله","نيكولاس","مادورو","تحتاج","لمعلومات","اخري؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785162024404);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('hG54YcEPI7Y1itr79Eto','سؤال الطالب: الرد إجابة البوصلة: طيب، عشان تدخل المنصة وتستفيد من المواد المجانية، ممكن تروح على موقع الأستاذ يوسف بركات أو تلاقي قناة الأستاذ يوسف بركات على اليوتيوب [قناة الأستاذ يوسف بركات](الرابط) و تشوف الفيديوهات المتاحة هناك كمان، ممكن تتابع الصفحات الرسمية للمنصة على وسائل التواصل الاجتماعي عشان تاخد كل التحديثات الجديدة أتمنى أكون ساعدتك!','["سءال","الطالب","الرد","اجابه","البوصله","طيب،","عشان","تدخل","المنصه","وتستفيد","المواد","المجانيه،","ممكن","تروح","علي","موقع","الاستاذ","يوسف","بركات","تلاقي","قناه","اليوتيوب","الرابط","تشوف","الفيديوهات","المتاحه","هناك","كمان،","تتابع","الصفحات","الرسميه","للمنصه","وساءل","التواصل","الاجتماعي","تاخد","التحديثات","الجديده","اتمني","اكون","ساعدتك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786465539922);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('hHOY5ucymDjXs0dFOIfa','سؤال الطالب: جزاك الله كل خير على مساعدتك ليا إجابة البوصلة: يا أيه، عفواً على الازعاج، لو محتاج أي حاجة تانية أو عندي إيه أساعدك فيه، متترددش في النزول علي، وأتمنى لك يوم سعيد وموفق إن شاء الله 🙏','["سءال","الطالب","جزاك","الله","خير","علي","مساعدتك","ليا","اجابه","البوصله","ايه،","عفواً","الازعاج،","محتاج","حاجه","تانيه","عندي","ايه","اساعدك","فيه،","متترددش","النزول","علي،","واتمني","يوم","سعيد","وموفق","شاء"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785870907326);
