INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('ihoikc1rHSWyfX8V1zXJ','**تأكد من الحروف الكبيرة و الصغيرة**: كلمة المرور حساسة لحجم الحروف، فلو كلمة المرور بتاعتك فيها حروف كبيرة و صغيرة، تأكد إنك بتكتبها بنفس الطريقة **تأكد من الرموز و الأرقام**: لو كلمة المرور بتاعتك فيها رموز أو أرقام، تأكد إنك بتكتبها بشكل صحيح **أعد تسجيل الدخول**: جرب أعد تسجيل الدخول و أكتب كلمة المرور تاني','["تاكد","الحروف","الكبيره","الصغيره","كلمه","المرور","حساسه","لحجم","الحروف،","فلو","بتاعتك","فيها","حروف","كبيره","صغيره،","انك","بتكتبها","بنفس","الطريقه","الرموز","الارقام","رموز","ارقام،","بشكل","صحيح","اعد","تسجيل","الدخول","جرب","اكتب","تاني"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785409873413);
