INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('mC7h0zelFj0ytJkPlQZh','سؤال الطالب: معاك الاستاذ يوسف بركات، اديني تفاصيل الحساب هل مشترك بكورس ولا لأ إجابة البوصلة: يا جنى يا جميل، أنا هنا لمساعدتك بالنسبة لمعلوماتك، أنت لست مشترك بأي كورسات حالياً إذا كنت تريد أن تعرف المزيد عن الكورسات المتاحة أو تريد الانضمام إلى كورس معين، أنا هنا لأساعدك.','["سءال","الطالب","معاك","الاستاذ","يوسف","بركات،","اديني","تفاصيل","الحساب","مشترك","بكورس","ولا","اجابه","البوصله","جني","جميل،","هنا","لمساعدتك","بالنسبه","لمعلوماتك،","لست","باي","كورسات","حالياً","كنت","تريد","تعرف","المزيد","الكورسات","المتاحه","الانضمام","الي","كورس","معين،","لاساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785359672174);
