INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('njNunqtKufT8hwVwWcau','سؤال الطالب: عامل ايه إجابة البوصلة: أنا مساعدك في المنصة التعليمية، ودي هنا لأجاوب على أسئلتك وافيدك في المواد الدراسية لو عندك أي سؤال أو محتاج شرح في حاجة معينة، قول لي وأنا هساعدك إن شاء الله.','["سءال","الطالب","عامل","ايه","اجابه","البوصله","مساعدك","المنصه","التعليميه،","ودي","هنا","لاجاوب","علي","اسءلتك","وافيدك","المواد","الدراسيه","عندك","محتاج","شرح","حاجه","معينه،","قول","وانا","هساعدك","شاء","الله"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785203397267);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('oSL4NwxKbAEARoVHnmwU','سؤال الطالب: يلا إجابة البوصلة: يا رؤى، هيا بنا نبدأ أنا هسألك عن الدرس الأول ممكن تقول لي إيه اللي فهمته من الدرس الأول أو لو عايز أساعدك في فهم نقطة معينة، أنا هنا عشان أشرح لك وأنا أذكرك أن المنصة دي أسرع منصة تعليمية، وشرح مبسط، ومتابعة مستمرة فلا تخاف من الأسئلة، وكن صريح مع نفسك','["سءال","الطالب","يلا","اجابه","البوصله","رءي،","هيا","بنا","نبدا","هسالك","الدرس","الاول","ممكن","تقول","ايه","اللي","فهمته","عايز","اساعدك","فهم","نقطه","معينه،","هنا","عشان","اشرح","وانا","اذكرك","المنصه","اسرع","منصه","تعليميه،","وشرح","مبسط،","ومتابعه","مستمره","فلا","تخاف","الاسءله،","وكن","صريح","نفسك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785755117352);
