INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('ospaBefkBcIrfl7MRDbM','سؤال الطالب: تمام شكرا جزاك الله خيرا إجابة البوصلة: على الرحب والسعة يا أيه، اتمنى لك يوم سعيد ومفيد مع الأستاذ يوسف بركات.','["سءال","الطالب","تمام","شكرا","جزاك","الله","خيرا","اجابه","البوصله","علي","الرحب","والسعه","ايه،","اتمني","يوم","سعيد","ومفيد","الاستاذ","يوسف","بركات"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785521542668);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('p07VnPyQxQqAdCdAkLnQ','سؤال الطالب: بتبقى مكتوبة ب نسبة مئوية إجابة البوصلة: أيوه يا كريمان، درجة التدريب بتاعتك هتكون مكتوبة بنسبة مئوية، هتلاقيها مكتوبة على شكل نسبة مثل 80% أو 90%، ده هيخليك تعرف إزاي مستواك و تقدر تحسن من نفسك.','["سءال","الطالب","بتبقي","مكتوبه","نسبه","مءويه","اجابه","البوصله","ايوه","كريمان،","درجه","التدريب","بتاعتك","هتكون","بنسبه","مءويه،","هتلاقيها","علي","شكل","هيخليك","تعرف","ازاي","مستواك","تقدر","تحسن","نفسك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785441815827);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('pIjuNC2JURbIU20mLLxi','سؤال الطالب: مش هو معقتل إجابة البوصلة: لا، أنا لست معقتل أنا برنامج حاسوبي مصمم لمساعدتك في الحصول على المعلومات والاجابة على أسئلتك أنا هنا لأساعدك في أي شيء تحتاج إليه، خاصة فيما يتعلق بالدراسات الاجتماعية هل هناك شيء محدد تريد أن أساعدك به؟','["سءال","الطالب","معقتل","اجابه","البوصله","لا،","لست","برنامج","حاسوبي","مصمم","لمساعدتك","الحصول","علي","المعلومات","والاجابه","اسءلتك","هنا","لاساعدك","شيء","تحتاج","اليه،","خاصه","فيما","يتعلق","بالدراسات","الاجتماعيه","هناك","محدد","تريد","اساعدك","به؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785162036707);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('pJSfCmtRy2jOkdZYjF8d','سؤال الطالب: كسمك إجابة البوصلة: أنا هنا لمساعدتك، بس معلش كلامك مش واضح بالنسبة لي أوي ممكن توضح سؤالك أو مشكلتك أكتر؟','["سءال","الطالب","كسمك","اجابه","البوصله","هنا","لمساعدتك،","معلش","كلامك","واضح","بالنسبه","اوي","ممكن","توضح","سءالك","مشكلتك","اكتر؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785203599530);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('pKffrpLltQj7sOpyoozq','إذا كنت تريد أن تتعلم من المستر يوسف بركات، يمكنك زيارة المنصة أو قناة اليوتيوب الخاصة به سوف تجد دروساً ممتعة ومفيدة، وستتمكن من التواصل معه مباشرة إذا كنت لديك أي أسئلة أو شكوك.','["كنت","تريد","تتعلم","المستر","يوسف","بركات،","يمكنك","زياره","المنصه","قناه","اليوتيوب","الخاصه","سوف","تجد","دروساً","ممتعه","ومفيده،","وستتمكن","التواصل","معه","مباشره","لديك","اسءله","شكوك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785202679497);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('pM3VREoH8ihBXOXLn4id','سؤال الطالب: لو سمحت هو التدريب لازم احله في خمس دقائق إجابة البوصلة: يا أيه، أنا فهمت، أنت بتقول إن التدريب لازم تحله في خمس دقائق، ودرجتك اتغيرت من 100% لدرجة تانية، أنا هساعدك في حل المشكلة دي، بس ممكن تسألني عن تفاصيل أكثر عن التدريب والدرجة اللي اتغيرت، عشان أقدر أفهم الوضع أفضل وأساعدك بشكل أفضل.','["سءال","الطالب","سمحت","التدريب","لازم","احله","خمس","دقاءق","اجابه","البوصله","ايه،","فهمت،","بتقول","تحله","دقاءق،","ودرجتك","اتغيرت","100","لدرجه","تانيه،","هساعدك","المشكله","دي،","ممكن","تسالني","تفاصيل","والدرجه","اللي","اتغيرت،","عشان","اقدر","افهم","الوضع","افضل","واساعدك","بشكل"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786205454192);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('pW4NeNqQhYn0WdPi4y0D','سؤال الطالب: انت ذكاء اصطناعي إجابة البوصلة: أنا ذكاء اصطناعي، صحيح أنا برنامج كمبيوتر متقدم مصمم لمساعدتك في إجابة أسئلتك وتقديم معلومات مفيدة لك أنا هنا لأساعدك في دراستك للدراسات الاجتماعية للمرحلة الإعدادية والثانوية، وأجيب على أسئلتك بأفضل طريقة ممكنة لو عندك أي سؤال أو محتاج مساعدة في شئ معين، ما تترددش في السؤال أنا هنا عشان أساعدك.','["سءال","الطالب","ذكاء","اصطناعي","اجابه","البوصله","اصطناعي،","صحيح","برنامج","كمبيوتر","متقدم","مصمم","لمساعدتك","اسءلتك","وتقديم","معلومات","مفيده","هنا","لاساعدك","دراستك","للدراسات","الاجتماعيه","للمرحله","الاعداديه","والثانويه،","واجيب","علي","بافضل","طريقه","ممكنه","عندك","محتاج","مساعده","معين،","تترددش","السءال","عشان","اساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785607330359);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('pnXt0KL39zeorWSzIoWk','سؤال الطالب: ليه كتبلي ٠%في امتحان المحاضرة التعريفية إجابة البوصلة: يا يوسف، لو حصلت ٠% في امتحان المحاضرة التعريفية، ممكن يكون السبب أنك لم تنجح في الإجابة على الأسئلة بشكل صحيح ممكن نراجع مع بعض المحاضرة ونحاول ن समझ نقطة ما لم تتفق.','["سءال","الطالب","ليه","كتبلي","امتحان","المحاضره","التعريفيه","اجابه","البوصله","يوسف،","حصلت","التعريفيه،","ممكن","يكون","السبب","انك","تنجح","الاجابه","علي","الاسءله","بشكل","صحيح","نراجع","ونحاول","نقطه","تتفق"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786060461650);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('pr4l5ZHvZRyDv6mYvMH2','سؤال الطالب: اعمل اي إجابة البوصلة: حسناً، يمكنك محاولة البحث عن الفيديو على قناة اليوتيوب باستخدام كلمات مفتاحية مثل "ثالثة إعدادي" أو "الأستاذ يوسف بركات" أو يمكنك زيارة الصفحة الرئيسية للقناة وتصفح الفيديوهات المتاحة','["سءال","الطالب","اعمل","اجابه","البوصله","حسناً،","يمكنك","محاوله","البحث","الفيديو","علي","قناه","اليوتيوب","باستخدام","كلمات","مفتاحيه","ثالثه","اعدادي","الاستاذ","يوسف","بركات","زياره","الصفحه","الرءيسيه","للقناه","وتصفح","الفيديوهات","المتاحه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785859564374);
