INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('qDAnRe2RduT4AsaWVBjX','سؤال الطالب: أنا خلصت الامتحان اجيب الدرجة منين إجابة البوصلة: يا أيه، بعد ما تخلص الامتحان، هتلاقي الدرجة في الداشبورد بتاعك في المنصة، هتلاقيها هناك بعد ما يتم تصحيح الامتحان، وانا هساعدك لو حابب تتعرف على أي حاجة تانية، بس لازم تنتظر شوية حتى يتم تصحيح الامتحان، وانا هساعدك في أي حاجة تانية تحتاجها.','["سءال","الطالب","خلصت","الامتحان","اجيب","الدرجه","منين","اجابه","البوصله","ايه،","تخلص","الامتحان،","هتلاقي","الداشبورد","بتاعك","المنصه،","هتلاقيها","هناك","يتم","تصحيح","وانا","هساعدك","حابب","تتعرف","علي","حاجه","تانيه،","لازم","تنتظر","شويه","حتي","تانيه","تحتاجها"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786040039569);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('qLoe6Sv9GrCAkFsaHjmO','سؤال الطالب: مين اشطر مدرس دراسات فى مصر إجابة البوصلة: يا بطل أنا هنا لأجيب على أسئلتك، ولكن أنا لا أستطيع أن أقول إن هناك مدرس واحد هو الأفضل في مصر كل مدرس لديه أسلوبه الخاص في التعليم، وكل طالب لديه احتياجاته الخاصة لكن إذا كنت تبحث عن مدرس دراسات اجتماعية متميز، يمكنني أن أقترح عليك المستر يوسف بركات','["سءال","الطالب","مين","اشطر","مدرس","دراسات","مصر","اجابه","البوصله","بطل","هنا","لاجيب","علي","اسءلتك،","ولكن","استطيع","اقول","هناك","واحد","الافضل","لديه","اسلوبه","الخاص","التعليم،","وكل","طالب","احتياجاته","الخاصه","كنت","تبحث","اجتماعيه","متميز،","يمكنني","اقترح","عليك","المستر","يوسف","بركات"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785202679213);
