INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('rhaswhyIgvd2iX5pjvXG','سؤال الطالب: لماذا المنصه هكذا إجابة البوصلة: المنصة دي مصممة عشان تكون أسرع منصة تعليمية، بتقدم شرح مبسط ومتابعة مستمرة، عشان نقدر نساعدك تنجح في دراستك بسهولة ويسر وأيضاً عشان نضمن لك تجربة تعليمية ممتعة ومفيدة، نقدر نتواصل معاك بسهولة ونتعرف على احتياجاتك وتساؤلاتك إذا كنت محتاج مساعدة في حاجة معينة أو عندك سؤال، أنا هنا عشان أساعدك','["سءال","الطالب","لماذا","المنصه","هكذا","اجابه","البوصله","مصممه","عشان","تكون","اسرع","منصه","تعليميه،","بتقدم","شرح","مبسط","ومتابعه","مستمره،","نقدر","نساعدك","تنجح","دراستك","بسهوله","ويسر","وايضاً","نضمن","تجربه","تعليميه","ممتعه","ومفيده،","نتواصل","معاك","ونتعرف","علي","احتياجاتك","وتساءلاتك","كنت","محتاج","مساعده","حاجه","معينه","عندك","سءال،","هنا","اساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785945554150);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('sIpDEzWeu14Us5OKeil0','سؤال الطالب: ازاي اعرف الدرس نزل ولا لا إجابة البوصلة: طبعًا، ممكن تتابع المنصة بشكل دوري عشان تلاقي الدرس الجديد لما ينزل أو ممكن تتابعنا على [قناة اليوتيوب](https://www.youtube.com/@youssefbarakat) أو [صفحة الفيسبوك](https://www.facebook.com/youssefbarakatofficial/) عشان تاخد آخر التحديثات','["سءال","الطالب","ازاي","اعرف","الدرس","نزل","ولا","اجابه","البوصله","طبعًا،","ممكن","تتابع","المنصه","بشكل","دوري","عشان","تلاقي","الجديد","لما","ينزل","تتابعنا","علي","قناه","اليوتيوب","https","www","youtube","com","youssefbarakat","صفحه","الفيسبوك","facebook","youssefbarakatofficial","تاخد","اخر","التحديثات"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785395140241);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('sZo2lX9OusFz59CpuL6z','سؤال الطالب: عايزه ادخل تدريب الدرس التاني الوحده الاولى إجابة البوصلة: يا ريماس، عشان تدخل تدريب الدرس التاني الوحدة الأولى، لازم تكون لما تكون مشترك في الكورس بتاع الدراسة دي أنت مش مشترك في أي كورسات حالياً إزاي أقدر أساعدك تلاقي كورس مناسب؟','["سءال","الطالب","عايزه","ادخل","تدريب","الدرس","التاني","الوحده","الاولي","اجابه","البوصله","ريماس،","عشان","تدخل","الاولي،","لازم","تكون","لما","مشترك","الكورس","بتاع","الدراسه","كورسات","حالياً","ازاي","اقدر","اساعدك","تلاقي","كورس","مناسب؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786647650368);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('sj3P0NDPtuOIETaZn3OY','سؤال الطالب: ممكن تشوف معلش أنا جبت كام في الامتحان علشان جيت ادور تاني على الدرجة مفيش إجابة البوصلة: يا أيه، أنا آسف، لكن أنا مش عارف أجيبلك الدرجة الحقيقية لأنها معلومات سرية و مش معروفه لي لكن أنا عارف أنك قلتلي إنك جبت 92 في الامتحان، و ده شيء كويس جداً لو عندك أي أسئلة أو محتاج مساعدة في أي حاجة، أنا هنا لأساعدك','["سءال","الطالب","ممكن","تشوف","معلش","جبت","كام","الامتحان","علشان","جيت","ادور","تاني","علي","الدرجه","مفيش","اجابه","البوصله","ايه،","اسف،","عارف","اجيبلك","الحقيقيه","لانها","معلومات","سريه","معروفه","انك","قلتلي","الامتحان،","شيء","كويس","جداً","عندك","اسءله","محتاج","مساعده","حاجه،","هنا","لاساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785443354693);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('t5Zxglop2GqROyXdzWYL','سؤال الطالب: اعمل ايه دلوقتي اتفرج ازاي علي اول الفيديو تالته اعدادي إجابة البوصلة: هجاوبك بكل سرور لو عايز تتشوف أول فيديو للصف الثالث الإعدادي، ممكن تروح على [قناة الأستاذ يوسف بركات](https://www.youtube.com/@youssefbarakat) على اليوتيوب وتبحث عن الفيديوهات الخاصة بالصف الثالث الإعدادي','["سءال","الطالب","اعمل","ايه","دلوقتي","اتفرج","ازاي","علي","اول","الفيديو","تالته","اعدادي","اجابه","البوصله","هجاوبك","بكل","سرور","عايز","تتشوف","فيديو","للصف","الثالث","الاعدادي،","ممكن","تروح","قناه","الاستاذ","يوسف","بركات","https","www","youtube","com","youssefbarakat","اليوتيوب","وتبحث","الفيديوهات","الخاصه","بالصف","الاعدادي"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785607300985);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('tL3B3JJZlCFK2LWgYGnz','إجابة البوصلة: يا أيه، قسم الحديث في المنصة بيغطي مواضيع مختلفة، وبيتناول الدولة الحديثة في أحد الفصول، بس أنا مش عارف بالظبط مين اللي بيشرح الفصل ده، لأننا في المنصة عندها مجموعة من الأساتذة اللي بيتناولوا المواضيع المختلفة، لو حابب تتعرف على المزيد عن الفصل ده أو تلاقي شرح ليه، ممكن تسألني وأنا هساعدك.','["اجابه","البوصله","ايه،","قسم","الحديث","المنصه","بيغطي","مواضيع","مختلفه،","وبيتناول","الدوله","الحديثه","احد","الفصول،","عارف","بالظبط","مين","اللي","بيشرح","الفصل","ده،","لاننا","عندها","مجموعه","الاساتذه","بيتناولوا","المواضيع","المختلفه،","حابب","تتعرف","علي","المزيد","تلاقي","شرح","ليه،","ممكن","تسالني","وانا","هساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786040140989);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('tVmdc84zRx9PjkYNcCF2','سؤال الطالب: دلوقتي عندي موضوع صعب إجابة البوصلة: يا حساب، موضوع صعب قوي ممكن تقول لي إزاي أنا هنا عشان أساعدك وأفهم معاك، ولو في حاجة مش واضحة أو محتاج شرح أكتر، هساعدك إن شاء الله إنت مشترك في الكورسات دي، ممكن تكون حاجة منهم هي اللي مش واضحة؟','["سءال","الطالب","دلوقتي","عندي","موضوع","صعب","اجابه","البوصله","حساب،","قوي","ممكن","تقول","ازاي","هنا","عشان","اساعدك","وافهم","معاك،","ولو","حاجه","واضحه","محتاج","شرح","اكتر،","هساعدك","شاء","الله","مشترك","الكورسات","دي،","تكون","منهم","اللي","واضحه؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785869967822);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('tWJpXJFqRiEQKbTkjABy','سؤال الطالب: لأ بتكلم على فنزويلا معقتل إجابة البوصلة: أحسنت نيكولاس مادورو هو رئيس فنزويلا الحالي، ولكن هناك خلاف حول شرعية حكمه بعض الدول لا تعترف به كرئيس شرعي لفنزويلا، وهم يعتبرون خوان غوايدو رئيسا مؤقتا هذا الخلاف يعود إلى انتخابات 2018 التي فاز بها مادورو، ولكنها كانت مثيرة للجدل هل تريد أن أعرف أكثر عن هذا الموضوع؟','["سءال","الطالب","بتكلم","علي","فنزويلا","معقتل","اجابه","البوصله","احسنت","نيكولاس","مادورو","رءيس","الحالي،","ولكن","هناك","خلاف","شرعيه","حكمه","الدول","تعترف","كرءيس","شرعي","لفنزويلا،","وهم","يعتبرون","خوان","غوايدو","رءيسا","مءقتا","الخلاف","يعود","الي","انتخابات","2018","فاز","بها","مادورو،","ولكنها","مثيره","للجدل","تريد","اعرف","الموضوع؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785162055979);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('tbOk9kkH8f6UNYaHqbjb','أو ممكن تتابعنا على [قناة اليوتيوب](https://www.youtube.com/@youssefbarakat) أو [صفحة الفيسبوك](https://www.facebook.com/youssefbarakatofficial/) أو تتواصل معنا على [الواتساب](https://wa.me/201023675235) عشان نساعدك أكتر.','["ممكن","تتابعنا","علي","قناه","اليوتيوب","https","www","youtube","com","youssefbarakat","صفحه","الفيسبوك","facebook","youssefbarakatofficial","تتواصل","معنا","الواتساب","201023675235","عشان","نساعدك","اكتر"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785437721468);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('u0vSubkRk6EoajMg7Txk','سؤال الطالب: هي اطول الجبال غير اعلي الجبال إجابة البوصلة: يا يوسف، اطول جبل في العالم هو جبل إيفرست، وهو كمان أعلى جبل في العالم فمفيش جبل اطول من إيفرست وأقل منه في الارتفاع.','["سءال","الطالب","اطول","الجبال","اعلي","اجابه","البوصله","يوسف،","جبل","العالم","ايفرست،","وهو","كمان","فمفيش","ايفرست","واقل","منه","الارتفاع"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786207576908);
