INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('ub3nCtDigcDwV1OALVb3','وتذكر، إذا في أي حاجة تحتاجيها، أتصل على 01023675235 أو تابعنا على [قناة اليوتيوب](https://www.youtube.com/@youssefbarakat) أو [صفحة الفيسبوك](https://www.facebook.com/youssefbarakatofficial/) أو [الواتساب](https://wa.me/201023675235).','["وتذكر،","حاجه","تحتاجيها،","اتصل","علي","01023675235","تابعنا","قناه","اليوتيوب","https","www","youtube","com","youssefbarakat","صفحه","الفيسبوك","facebook","youssefbarakatofficial","الواتساب","201023675235"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785798504041);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('unYZr2v1GfJSxtI7oDRD','سؤال الطالب: عندما ادخل المحاضر يحدث خطا ولا استطيع الاستماع للمحاضرة إجابة البوصلة: يا جني، آسف جداً لأنك واجهت مشكلة حاول تقوم بإعادة تشغيل الجهاز أو المتصفح، ولو المشكلة لسه موجودة، ممكن تتواصل مع الدعم الفني على 01023675235 عشان يساعدك بشكل أفضل.','["سءال","الطالب","عندما","ادخل","المحاضر","يحدث","خطا","ولا","استطيع","الاستماع","للمحاضره","اجابه","البوصله","جني،","اسف","جداً","لانك","واجهت","مشكله","حاول","تقوم","باعاده","تشغيل","الجهاز","المتصفح،","ولو","المشكله","لسه","موجوده،","ممكن","تتواصل","الدعم","الفني","علي","01023675235","عشان","يساعدك","بشكل","افضل"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786611536512);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('upqxnK9aK0w5zvodAcPb','إذا كنت بحاجة إلى التواصل المباشر، يمكنك الاتصال على رقم 01023675235 تاًمنياتي لك بالتوفيق في دراستك!','["كنت","بحاجه","الي","التواصل","المباشر،","يمكنك","الاتصال","علي","رقم","01023675235","تاًمنياتي","بالتوفيق","دراستك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785162217742);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('uwcc4Aq5aPbEzFxsXQrl','سؤال الطالب: ادخل المنصه ازى انا من الناس المنهج مجانا إجابة البوصلة: طبعاً أنت ممكن تدخل المنصة عن طريق الموقع الرسمي للأستاذ يوسف بركات، و هتلاقي قسم خاص بالمنهج المجاني، هناك هتلاقي كل المواد و الشرح و التدريب و الواجب و الامتحانات و أنا هنا عشان أساعدك فى أي سؤال أو مشكلة هتلاقيها.','["سءال","الطالب","ادخل","المنصه","ازي","الناس","المنهج","مجانا","اجابه","البوصله","طبعاً","ممكن","تدخل","طريق","الموقع","الرسمي","للاستاذ","يوسف","بركات،","هتلاقي","قسم","خاص","بالمنهج","المجاني،","هناك","المواد","الشرح","التدريب","الواجب","الامتحانات","هنا","عشان","اساعدك","مشكله","هتلاقيها"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786465539817);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('v37TjSq83uuoMoOgbYjY','سؤال الطالب: تلقائي من نفسك لما يتم الاشتراك ابعت إجابة البوصلة: يا جنى يا بطل، متوفرش معلومات عن اشتراكاتك الحالية لأنك لم تشترك بأي كورسات بعد إذا كنت تريد أن تعرف المزيد عن الكورسات أو تريد أن تشترك في كورس معين، أنا هنا لأساعدك','["سءال","الطالب","تلقاءي","نفسك","لما","يتم","الاشتراك","ابعت","اجابه","البوصله","جني","بطل،","متوفرش","معلومات","اشتراكاتك","الحاليه","لانك","تشترك","باي","كورسات","كنت","تريد","تعرف","المزيد","الكورسات","كورس","معين،","هنا","لاساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785359714482);
