INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('vtaPweRVpG4YJptRvIDN','سؤال الطالب: أنا خلصت الإمتحان اعمل اي بقت إجابة البوصلة: يا ندى، مبروك عليكي خلصت الإمتحان دلوقتي تقدري تروحي تشوفي درجاتك على المنصة، أو تطلعي على كورساتك وتستعدي للكورس اللي جاي، أو حتى تروحي تشوفي فيديوهات شرح جديدة على [قناة الأستاذ يوسف بركات](الرابط) على اليوتيوب','["سءال","الطالب","خلصت","الامتحان","اعمل","بقت","اجابه","البوصله","ندي،","مبروك","عليكي","دلوقتي","تقدري","تروحي","تشوفي","درجاتك","علي","المنصه،","تطلعي","كورساتك","وتستعدي","للكورس","اللي","جاي،","حتي","فيديوهات","شرح","جديده","قناه","الاستاذ","يوسف","بركات","الرابط","اليوتيوب"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786041688029);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('vxuMDFEyT56IXFuu74xJ','سؤال الطالب: مش عارفه اشترك في المنصه إجابة البوصلة: لا تقلق، أنا هنا لأساعدك','["سءال","الطالب","عارفه","اشترك","المنصه","اجابه","البوصله","تقلق،","هنا","لاساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785232971973);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('w0rP0RZ9XKa16zk9qXcm','سؤال الطالب: حفظهالي اديني قصة بسيطة احفظهم إجابة البوصلة: حسنًا، يا بطل قصة بسيطة لحفظ جبال قارات العالم الجديد: "روكي راقص في الأنديز" روكي بيرمونت في أمريكا الشمالية، والأنديز في أمريكا الجنوبية وأنت تقدر تزيد عليها، زي: "روكي راقص مع الأندز في أمريكا، وآسيا لها جبال الهيمالايا" هكذا تقدر تحفظ جبال قارات العالم الجديد بطريقة سهلة وممتعة','["سءال","الطالب","حفظهالي","اديني","قصه","بسيطه","احفظهم","اجابه","البوصله","حسنًا،","بطل","لحفظ","جبال","قارات","العالم","الجديد","روكي","راقص","الانديز","بيرمونت","امريكا","الشماليه،","والانديز","الجنوبيه","وانت","تقدر","تزيد","عليها،","الاندز","امريكا،","واسيا","لها","الهيمالايا","هكذا","تحفظ","بطريقه","سهله","وممتعه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785203539422);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('w5tfuUF2iqF74VNI579M','سؤال الطالب: اخر تحديث للمنصة إجابة البوصلة: يا كريمان، أخر تحديث للمنصة كان مؤخرًا، ولكن أنا لا أملك معلومات دقيقة عن تاريخ التحديث الأخير إذا كنت محتاج تعرف تفاصيل عن التحديثات، أقدر أن أقول لك إن المنصة دايماً بتتحسن وبتطور لتقديم أفضل تجربة للاستفادة من المحتوى التعليمي إذا كان في حاجة محددة بتحاول تعرفها، قول لي عشان أساعدك.','["سءال","الطالب","اخر","تحديث","للمنصه","اجابه","البوصله","كريمان،","مءخرًا،","ولكن","املك","معلومات","دقيقه","تاريخ","التحديث","الاخير","كنت","محتاج","تعرف","تفاصيل","التحديثات،","اقدر","اقول","المنصه","دايماً","بتتحسن","وبتطور","لتقديم","افضل","تجربه","للاستفاده","المحتوي","التعليمي","حاجه","محدده","بتحاول","تعرفها،","قول","عشان","اساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786439935906);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('wAZEC7cIMbeA8UFUDuRP','سؤال الطالب: ازاي ادخل على صراع البوصلة إجابة البوصلة: لو بتبحث عن طريقة لدخول صراع البوصلة، ممكن تقول لي أكثر عن ما بتبحث عنه هي صفحة على المنصة أم حاجة تانية أنا هنا عشان أساعدك وأقدم لك المعلومات اللي تحتاجها.','["سءال","الطالب","ازاي","ادخل","علي","صراع","البوصله","اجابه","بتبحث","طريقه","لدخول","البوصله،","ممكن","تقول","عنه","صفحه","المنصه","حاجه","تانيه","هنا","عشان","اساعدك","واقدم","المعلومات","اللي","تحتاجها"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785868506165);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('wQFsrJbfubIcLkO8T0M3','سؤال الطالب: عندي مشكلة في الدفع إجابة البوصلة: يا حساب، آسف إنك واجهت مشكلة في الدفع ممكن تساعدني أكتر وتقولي لي عن المشكلة بالضبط عشان أستطع أساعدك أحلها معاك.','["سءال","الطالب","عندي","مشكله","الدفع","اجابه","البوصله","حساب،","اسف","انك","واجهت","ممكن","تساعدني","اكتر","وتقولي","المشكله","بالضبط","عشان","استطع","اساعدك","احلها","معاك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786015232703);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('wSa1wn7BtuRySLKxocZM','سؤال الطالب: لااا إجابة البوصلة: يا رؤى، متقلقش، هساعدك ترتيب قارات العالم الجديد، يعني أمريكا الشمالية وأمريكا الجنوبية، هي كالتالي: أمريكا الشمالية ثم أمريكا الجنوبية.','["سءال","الطالب","لااا","اجابه","البوصله","رءي،","متقلقش،","هساعدك","ترتيب","قارات","العالم","الجديد،","يعني","امريكا","الشماليه","وامريكا","الجنوبيه،","كالتالي","الجنوبيه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785754552247);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('wWm9ojccPQTuTRkBpbMF','سؤال الطالب: هل اشتراك في الكورس كله بكام في ثالثه اعدادي إجابة البوصلة: يا ahmed، أنا آسف، لكن مافيش معلومات عن أسعار الكورسات في النظام، تقدر تتواصل مع الدعم الفني على رقم 01023675235 عشان يساعدك في الأسعار والاشتراكات.','["سءال","الطالب","اشتراك","الكورس","كله","بكام","ثالثه","اعدادي","اجابه","البوصله","ahmed،","اسف،","مافيش","معلومات","اسعار","الكورسات","النظام،","تقدر","تتواصل","الدعم","الفني","علي","رقم","01023675235","عشان","يساعدك","الاسعار","والاشتراكات"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786908616017);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('xDSbHsto3B4UuA4Ke1pa','سؤال الطالب: طيب أنا عملت ده كله إجابة البوصلة: يا أيه، لو عملت كل اللي قولتهولك و لسه مش دخلت المحاضرة، ممكن يكون في حاجة بسيطة نحتاج نضيفها أو نصححها ممكن تساعدني وتقولي لي المفتاح السري بتاعك عشان أساعدك أكتر أو ممكن تتواصل معنا على رقم الدعم الفني أو تتواصل مع الأستاذ يوسف بركات على رقم 01023675235 عشان يساعدك في دخول المحاضرة.','["سءال","الطالب","طيب","عملت","كله","اجابه","البوصله","ايه،","اللي","قولتهولك","لسه","دخلت","المحاضره،","ممكن","يكون","حاجه","بسيطه","نحتاج","نضيفها","نصححها","تساعدني","وتقولي","المفتاح","السري","بتاعك","عشان","اساعدك","اكتر","تتواصل","معنا","علي","رقم","الدعم","الفني","الاستاذ","يوسف","بركات","01023675235","يساعدك","دخول","المحاضره"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785437763900);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('xEkmFPpiqUo6cLfuUBNH','سؤال الطالب: المحاضرة الساعة كام إجابة البوصلة: يا حساب، مواعيد المنصة الثابتة، للمرحلة الإعدادية المحاضرة والتدريب يوم الخميس، والواجب يوم الثلاثاء، والامتحان يوم الأربعاء الساعة 9 مساءً والمرحلة الثانوية المحاضرة والتدريب يوم الجمعة، والواجب يوم الثلاثاء، والامتحان يوم الأربعاء الساعة 9 مساءً.','["سءال","الطالب","المحاضره","الساعه","كام","اجابه","البوصله","حساب،","مواعيد","المنصه","الثابته،","للمرحله","الاعداديه","والتدريب","يوم","الخميس،","والواجب","الثلاثاء،","والامتحان","الاربعاء","مساءً","والمرحله","الثانويه","الجمعه،"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785796407949);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('xVf807vjN0zuOaqez0qB','سؤال الطالب: هو ازاي اعرف درجة تدريب المحاضرة التعريفية إجابة البوصلة: يا كريمان، تقدر تلاقي درجة التدريب بتاعتك في المحاضرة التعريفية من خلال الدخول على المنصة وفتح الكورس اللي أنتا مشترك فيه، وبعدين تروح على صفحه التدريب و هتلاقي درجتك هناك لو محتاج مساعدة أكتر، أنا هنا عشان أساعدك.','["سءال","الطالب","ازاي","اعرف","درجه","تدريب","المحاضره","التعريفيه","اجابه","البوصله","كريمان،","تقدر","تلاقي","التدريب","بتاعتك","الدخول","علي","المنصه","وفتح","الكورس","اللي","انتا","مشترك","فيه،","وبعدين","تروح","صفحه","هتلاقي","درجتك","هناك","محتاج","مساعده","اكتر،","هنا","عشان","اساعدك"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785441740801);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('y7gkCFdaOEWpOVk03czh','وإذا كنت محتاج تتكلم مع الإدارة، ممكن تتصل على [01023675235](https://wa.me/201023675235) أو تتواصل معنا من خلال [قناة اليوتيوب](https://www.youtube.com/@youssefbarakat) أو [صفحة الفيسبوك](https://www.facebook.com/youssefbarakatofficial/) أو [الواتساب](https://wa.me/201023675235).','["واذا","كنت","محتاج","تتكلم","الاداره،","ممكن","تتصل","علي","01023675235","https","201023675235","تتواصل","معنا","قناه","اليوتيوب","www","youtube","com","youssefbarakat","صفحه","الفيسبوك","facebook","youssefbarakatofficial","الواتساب"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785945554451);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('y9bx2x43hRpTnSw1doQl','سؤال الطالب: شكراً كنتي مفيدة إجابة البوصلة: على الرحب والسعة أنا سعيد إن كنت استفدت من المساعدة لو في أي سؤال أو حاجة تانية تحتاجيها، مينفعش تتردد في السؤال اتمنى لك يوم سعيد ومستقبل زاهر','["سءال","الطالب","شكراً","كنتي","مفيده","اجابه","البوصله","علي","الرحب","والسعه","سعيد","كنت","استفدت","المساعده","حاجه","تانيه","تحتاجيها،","مينفعش","تتردد","السءال","اتمني","يوم","ومستقبل","زاهر"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785798503646);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('yB1XAlMOBVBeVUIIQu0e','سؤال الطالب: اختبار اول درس إجابة البوصلة: يا رؤى، عشان نبدأ اختبار أول درس، أنا محتاج أعرف مينفعش أستخدم بياناتك اللي عندنا ممكن تساعدني وأتأكد إنك مشترك في الكورس c1785241200444 لو مؤكد إنك مشترك، ممكن نبدأ اختبار أول درس أنا هسألك أسئلة عن الدرس الأول، ونتكلم عن إجاباتك هتكون تجربة ممتعة ومفيدة','["سءال","الطالب","اختبار","اول","درس","اجابه","البوصله","رءي،","عشان","نبدا","درس،","محتاج","اعرف","مينفعش","استخدم","بياناتك","اللي","عندنا","ممكن","تساعدني","واتاكد","انك","مشترك","الكورس","c1785241200444","مءكد","مشترك،","هسالك","اسءله","الدرس","الاول،","ونتكلم","اجاباتك","هتكون","تجربه","ممتعه","ومفيده"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785754830309);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('yOHnqNC16SjJav9ShDbM','سؤال الطالب: الحصص متسجلة وللا لايف مع الطالب إجابة البوصلة: طبعًا، الحصص عندنا متسجلة ومتاحة للاستخدام في أي وقت، وبالتالي ممكن تلاقي كل الحصص السابقة وترجع ليها في أي وقت تريد وبالنسبة للحصص اللايف، فهي بتتم بشكل مباشر مع الأستاذ يوسف بركات، وبيتم بثها على قناة [قناة الأستاذ يوسف بركات](الرابط) على اليوتيوب','["سءال","الطالب","الحصص","متسجله","وللا","لايف","اجابه","البوصله","طبعًا،","عندنا","ومتاحه","للاستخدام","وقت،","وبالتالي","ممكن","تلاقي","السابقه","وترجع","ليها","وقت","تريد","وبالنسبه","للحصص","اللايف،","فهي","بتتم","بشكل","مباشر","الاستاذ","يوسف","بركات،","وبيتم","بثها","علي","قناه","بركات","الرابط","اليوتيوب"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786048563573);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('yOWY7A65w62u3sp7PVQg','سؤال الطالب: o951@j1v&7 إجابة البوصلة: يا رؤى، آسف لكن أنا مش عارف إيه اللي بتقصد بذلك هل ده مفتاح سري أو رمز لو ده مفتاح سري، ممكن تساعدني وتقوله لي بطريقة أمنة أنا هنا عشان أساعدك، وانا محتاج أتأكد إنك أنت اللي بتتكلم معايا لو عايز تساعدني، ممكن تقول لي إيه اللي بتحاول تعمله؟','["سءال","الطالب","o951","j1v","اجابه","البوصله","رءي،","اسف","عارف","ايه","اللي","بتقصد","بذلك","مفتاح","سري","رمز","سري،","ممكن","تساعدني","وتقوله","بطريقه","امنه","هنا","عشان","اساعدك،","وانا","محتاج","اتاكد","انك","بتتكلم","معايا","عايز","تساعدني،","تقول","بتحاول","تعمله؟"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785755083715);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('zL1Bi7i8KMx72PJHjNyt','سؤال الطالب: الباسورد إجابة البوصلة: إذا نسيت كلمة المرور (الباسورد)، لا تقلق يمكنك إعادة تعيين كلمة المرور بسهولة يمكنك النقر على خيار "نسيت كلمة المرور" على صفحة تسجيل الدخول، وستتم إرسال تعليمات إعادة التعيين إلى بريدك الإلكتروني','["سءال","الطالب","الباسورد","اجابه","البوصله","نسيت","كلمه","المرور","تقلق","يمكنك","اعاده","تعيين","بسهوله","النقر","علي","خيار","صفحه","تسجيل","الدخول،","وستتم","ارسال","تعليمات","التعيين","الي","بريدك","الالكتروني"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785436332773);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('zcKEuwUTyjsntxfgkj2D','سؤال الطالب: بيعلق ومش راضي يفتح إجابة البوصلة: حاول تقفل المتصفح وتفتحه تاني، أو جرب تستخدم متصفح تاني، أو اعمل ريستارت للجهاز بتاعك إذا لسه مش شغال، ممكن تتواصل مع الدعم الفني على 01023675235.','["سءال","الطالب","بيعلق","ومش","راضي","يفتح","اجابه","البوصله","حاول","تقفل","المتصفح","وتفتحه","تاني،","جرب","تستخدم","متصفح","اعمل","ريستارت","للجهاز","بتاعك","لسه","شغال،","ممكن","تتواصل","الدعم","الفني","علي","01023675235"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786129334971);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('zfMfol0pQ37QDAvJPFRp','سؤال الطالب: اعمل ايه إجابة البوصلة: أنا هنا عشان أساعدك في دراستك، فحسب ما تحتاجه إنت عايز تسأل عن دروس معينة في الدراسات الاجتماعية أو عايز تتعلم حاجة جديدة أو ربما عايز تتدرب على أسئلة امتحانات قول لي عشان أساعدك بأفضل طريقة وإذا كنت عايز تتواصل مع الأستاذ يوسف بركات أو الإدارة، هتلاقي الرقم ده [01023675235](https://wa.me/201023675235)','["سءال","الطالب","اعمل","ايه","اجابه","البوصله","هنا","عشان","اساعدك","دراستك،","فحسب","تحتاجه","عايز","تسال","دروس","معينه","الدراسات","الاجتماعيه","تتعلم","حاجه","جديده","ربما","تتدرب","علي","اسءله","امتحانات","قول","بافضل","طريقه","واذا","كنت","تتواصل","الاستاذ","يوسف","بركات","الاداره،","هتلاقي","الرقم","01023675235","https","201023675235"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785343779215);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('zfUtYFFQHZeq2sA880y7','وإذا كنت محتاج مساعدة في حاجة تانية، زي شرح دروس أو فهم مفاهيم معينة في الدراسات الاجتماعية، أنا هنا لمساعدتك كمان!','["واذا","كنت","محتاج","مساعده","حاجه","تانيه،","شرح","دروس","فهم","مفاهيم","معينه","الدراسات","الاجتماعيه،","هنا","لمساعدتك","كمان"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1785588853012);
INSERT INTO "self_learning_pending" ("id","text","keywords","grade","unit","subject","status","created_at") VALUES('znkKTVoeUIkiF3gIRjv2','إحتفلي بنجاحك ده، ومتنساش إنك كنتي قويه ومتفوقه!','["احتفلي","بنجاحك","ده،","ومتنساش","انك","كنتي","قويه","ومتفوقه"]','تعلم ذاتي','أسئلة الطلاب','دراسات اجتماعية','pending',1786392151864);
INSERT INTO "intents" ("core_id","intent","category","answer","variations") VALUES('Q_001','الطقس_والمناخ','academic','الطقس هو حالة الجو خلال فترة قصيرة، أما المناخ فهو متوسط حالة الجو خلال فترة زمنية طويلة في مكان معين. (الطقس = فترة قصيرة، المناخ = فترة طويلة)','["ما الفرق بين الطقس والمناخ؟","ايه الفرق بين الطقس والمناخ؟","الفرق بين الطقس والمناخ؟","عرف الفرق بين الطقس والمناخ.","قارن بين الطقس والمناخ.","ما أوجه الاختلاف بين الطقس والمناخ؟","وضح الفرق بين الطقس والمناخ.","الطقس والمناخ نفس الحاجة؟","الطقس غير المناخ؟","هل الطقس يختلف عن المناخ؟","ما المقصود بالطقس والمناخ؟","الطقس يعني ايه والمناخ يعني ايه؟","اشرح الفرق بين الطقس والمناخ.","ممكن تشرح الفرق بين الطقس والمناخ؟","الطقس والمناخ ايه الفرق؟","اي الفرق بين المناخ والطقس؟","ما الفرق بين المناخ والطقس؟","قارن بين المناخ والطقس.","الفرق بين المناخ والطقس في الدراسات.","سؤال الفرق بين الطقس والمناخ.","هو الطقس زي المناخ؟","يعني ايه طقس ويعني ايه مناخ؟","المناخ والطقس مش فاهمهم.","وضحلي الفرق بين الطقس والمناخ.","الطقس والمناخ فرقهم ايه؟","ايه الاختلاف بين الطقس والمناخ؟","فرق الطقس عن المناخ.","الطقس والمناخ في الجغرافيا.","اشرحلي الطقس والمناخ.","الفرق بين الطقس والمناخ باختصار.","ايه هو الطقس","ايه هو المناخ","تعريف الطقس","تعريف المناخ","الطقس والمناخ يفرقو ايه عن بعض","شرح درس الطقس والمناخ","الطقس والمناخ والفرق بينهم","الطقس","المناخ","يعني اي طقس","يعني اي مناخ"]');
INSERT INTO "intents" ("core_id","intent","category","answer","variations") VALUES('Q_002','قيام_الحضارة_المصرية','academic','قامت الحضارة المصرية على ضفاف نهر النيل لتوافر المياه، وخصوبة التربة، وقيام الزراعة، وسهولة النقل والاتصال، واستقرار السكان.','["علل قيام الحضارة المصرية القديمة على ضفاف نهر النيل.","لماذا قامت الحضارة المصرية على نهر النيل؟","ليه قامت الحضارة المصرية على ضفاف النيل؟","ما سبب قيام الحضارة المصرية على نهر النيل؟","اذكر سبب قيام الحضارة المصرية على النيل.","لماذا استقرت الحضارة المصرية حول نهر النيل؟","ما أسباب قيام الحضارة المصرية القديمة؟","لماذا كان نهر النيل أساس الحضارة المصرية؟","كيف ساعد نهر النيل على قيام الحضارة؟","علل أهمية نهر النيل للحضارة المصرية.","ليه المصريين القدماء عاشوا جنب النيل؟","سبب قيام الحضارة بجوار النيل؟","اشرح سبب قيام الحضارة المصرية على النيل.","لماذا ارتبطت الحضارة المصرية بالنيل؟","دور نهر النيل في قيام الحضارة المصرية.","كيف ساهم نهر النيل في نشأة الحضارة؟","النيل ساعد في قيام الحضارة ليه؟","ما أهمية نهر النيل للمصريين القدماء؟","علل اعتماد المصريين القدماء على النيل.","لماذا قامت الحضارة بالقرب من النيل؟","النيل كان سبب الحضارة؟","ايه علاقة النيل بالحضارة المصرية؟","وضح دور النيل في الحضارة.","لماذا ازدهرت الحضارة المصرية عند النيل؟","ما العوامل التي ساعدت على قيام الحضارة المصرية؟","علل نشأة الحضارة المصرية القديمة.","سبب ازدهار الحضارة المصرية القديمة.","النيل والحضارة المصرية.","كيف قامت الحضارة المصرية؟","علل أهمية نهر النيل في نشأة الحضارة.","بم تفسر قيام الحضارة المصرية","بم تفسر اهمية نهر النيل","ليه الحضارة المصريه قامت علي النيل","اهميه نهر النيل قديما","اسباب قيام الحضاره المصريه القديمه","العوامل الطبيعيه لقيام الحضاره"]');
